window.MS_OVERGANGE={"version":"2026-10-21","templates":[{"id":"portal","navn":"Portal","kort":"Den nye verden åbner sig som en rund portal i midten, og kameraet flyver ind i den.","kategori":"skærm","look":"portal","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":"MondayMonday kap. 11 (30:17.9, 1.6 s), kap. 23 (52:58.1, 1.5 s); Snuiffe kap. 5 (38:58.5, 10.7 s); Jam kap. 2 (02:01.7, 13.4 s), kap. 3 (04:14.3, 12.4 s)"},{"id":"depth","navn":"Dybde","kort":"Den nye verden stiger op af dybet: en usynlig front glider fra horisonten ind mod kameraet.","kategori":"skærm","look":"depth","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":"Video har ingen dybde: MedieStudio regner en dybde ud (midten langt væk, kanterne og lyse ting tæt på).","brugt_i":"175BPM kap. 2 (00:40.6, 11.1 s), kap. 10 (22:17.9, 23.6 s); No Words kap. 3 (04:54.5, 10.8 s), kap. 5 (11:19.1, 10.1 s); MondayMonday kap. 7 (19:31.6, 12.8 s), kap. 19 (43:43.5, 12.2 s); DaddyCums kap. 2 (00:27.7, 1.5 s), kap. 6 (10:20.5, 1.6 s); Snuiffe kap. 3 (16:25.1, 11.9 s), kap. 7 (44:28.2, 10.8 s)"},{"id":"bloom","navn":"Lotus","kort":"En lotus folder sig ud fra midten, og den nye verden ses gennem kronbladene.","kategori":"skærm","look":"bloom","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":"No Words kap. 2 (00:51.5, 1.2 s), kap. 6 (13:45.0, 10.5 s); MondayMonday kap. 13 (33:08.0, 1.6 s), kap. 25 (57:00.5, 12.2 s); Snuiffe kap. 2 (04:07.1, 12.6 s)"},{"id":"weave","navn":"Væv","kort":"Den nye verden væves ind gennem spiraltråde, der krydser over og under hinanden som en kurv.","kategori":"skærm","look":"weave","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":"175BPM kap. 4 (07:50.0, 42.1 s), kap. 11 (23:21.2, 10.0 s); MondayMonday kap. 5 (13:15.1, 13.1 s), kap. 17 (39:15.4, 13.2 s); Snuiffe kap. 4 (33:48.7, 13.3 s), kap. 6 (41:19.4, 11.7 s)"},{"id":"marble","navn":"Marmor","kort":"Den nye verden flyder ind som marmoreret maling i bugtede årer (fra hans maleri Liquid Embrace).","kategori":"skærm","look":"marble","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":"Variablen 'cast' omdøbes: ordet er reserveret i WebGL.","brugt_i":"No Words kap. 4 (09:07.8, 10.2 s), kap. 7 (16:05.3, 1.3 s); MondayMonday kap. 9 (24:00.6, 1.6 s), kap. 21 (48:28.6, 12.4 s)"},{"id":"prism","navn":"Prisme","kort":"En sværm af tumlende krystaller viser den nye verden brudt gennem glasset.","kategori":"skærm","look":"prism","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":"MondayMonday kap. 3 (08:54.5, 12.7 s), kap. 15 (37:31.0, 1.6 s)"},{"id":"shutter","navn":"Rulleport","kort":"En tung rulleport af stål går ned i hak på beatet og bærer den nye verden på lamellerne.","kategori":"skærm","look":"shutter","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":"Hakkene lander på slag, når varigheden er hele takter, og snittet ligger på et slag.","brugt_i":"DaddyCums kap. 3 (02:35.2, 12.5 s), kap. 7 (11:42.3, 6.9 s)"},{"id":"slam","navn":"Presse","kort":"En hydraulisk presse lukker i hak på beatet; pladerne bærer hver sin halvdel af den nye verden.","kategori":"skærm","look":"slam","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":"DaddyCums kap. 4 (02:57.9, 10.8 s), kap. 5 (06:15.0, 12.4 s)"},{"id":"crossfader","navn":"Crossfader","kort":"Mixerens crossfader gjort synlig: en lodret søm med fader-knap glider hen over billedet.","kategori":"skærm","look":"crossfader","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":""},{"id":"frame","navn":"Billedramme","kort":"Et svævende billede i neon-ramme flyver mod kameraet, viser den nye verden og flyves igennem på droppet.","kategori":"skærm","look":"frame","placering":"efter","kurve":"blød","slag":8,"b_look":null,"noter":"Uden film: rammen viser B fra starten.","brugt_i":"MondayMonday kap. 2 (04:25.0, 13.2 s), kap. 4 (11:00.1, 18.8 s)"},{"id":"gate","navn":"Gate","kort":"Gateren gjort synlig: billedet skæres i 21 lameller, der skifter mellem A og B på hver sekstendedel.","kategori":"skærm","look":"gate","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":""},{"id":"collapse","navn":"Kollaps","kort":"Den gamle verden løber ud i et afløb og bliver til en svag glød; den nye vælter ud af gløden.","kategori":"skærm","look":"collapse","placering":"efter","kurve":"blød","slag":16,"b_look":null,"noter":null,"brugt_i":""},{"id":"vokser","navn":"Vokser ud","kort":"Den nye verden breder sig ud fra ét punkt med en organisk, langsomt drivende kant.","kategori":"skærm","look":"vokser","placering":"efter","kurve":"blød","slag":4,"b_look":null,"noter":null,"brugt_i":"175BPM bro 2 (02:57.2, ribbon->serpent, fold/coil), bro 4 (10:02.2, leaf->embers, sink/merge); 4D bro 1 (03:12.8, bubbles->bird, fog/plant), bro 2 (04:23.3, ribbon->vine, fold/plant)"},{"id":"mixover","navn":"Lang mixover","kort":"Hans egen mixover: overgangen starter, hvor han begynder at mixe, og er fuldbyrdet, når det nye nummer er inde.","kategori":"timing","look":"weave","placering":"foer","kurve":"blød","slag":16,"b_look":null,"noter":null,"brugt_i":"175BPM kap. 4 (07:50.0, 42.1 s), kap. 10 (22:17.9, 23.6 s); No Words kap. 3 (04:54.5, 10.8 s), kap. 6 (13:45.0, 10.5 s); DaddyCums kap. 7 (11:42.3, 6.9 s)"},{"id":"mixover-kick","navn":"Raiser + kick-trin","kort":"Overgangen kryber til 30 % over raiseren og rykker et trin frem på hvert kick, til den er fuldbyrdet.","kategori":"timing","look":"slam","placering":"foer","kurve":"trin","slag":8,"b_look":null,"noter":null,"brugt_i":"DaddyCums kap. 4 (02:57.9, 10.8 s)"},{"id":"selv","navn":"Flet sig ind i sig selv","kort":"Samme verden fletter sig ind i sig selv: et nyt kamera og en ny palet væves ind over den gamle.","kategori":"samme-verden","look":"weave","placering":"foer","kurve":"blød","slag":8,"b_look":{"varm":true,"kreds":true},"noter":"Til et klip, der er delt: B er samme video med varm farve (ild) og kredsende kamera.","brugt_i":"175BPM kap. 11 (23:21.2, 10.0 s)"}],"shaders":{"portal":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift i 3D: den nye verden vokser ud fra centrum som en portal, kameraet flyver ind i den.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nout vec4 fragColor;\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    vec4 a = texture(uA, tc), b = texture(uB, tc);\n    float r = length(uv), R = uMix * 1.3;\n    vec4 c = mix(b, a, smoothstep(R - 0.2, R + 0.02, r));\n    float w = 0.006;\n    c.rgb += uSeam * (w * w / ((r - R) * (r - R) + w * w)) * 0.3 * (1.0 - abs(2.0 * uMix - 1.0));\n    fragColor = c;\n}\n","depth":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"depth\": den nye verden stiger op af dybet. En usynlig front glider fra horisonten ind mod kameraet;\n// alt bag fronten er allerede den nye verden, alt foran den er stadig den gamle. Den gamle verdens nære strukturer\n// står derfor tilbage foran den nye og opløses til sidst som hele former (med glorie), mens kameraet flyver igennem\n// dem; den nye verdens nære strukturer toner frem, når fronten når dem. Masken bygger på \"lysets dybde i området\":\n// en lysvægtet log-dybde over en skive på ~2,5 % af højden, så en linjes glorie hører til samme dybde som linjen, og\n// tynde linjer ikke skæres i stykker. Fronten tegner en svag kontur i sømfarven på det, den netop når.\n// Ingen lysstyrke følger musikken; uBeat bruges ikke.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\nconst float BB = 0.45;          // blød kant i log-dybde på B's side (faktor ~1,6)\nconst float BA = 0.50;          // og på A's side\nconst int NT = 12;              // antal prøver i skiven\nconst float RAD = 56.0;         // skivens radius i (supersamplede) pixels\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\n\n// B kommer nærmere: en pr. akse forvrængning, der er nøjagtig ved billedkanten (ingen spejling, ingen kantstriber)\nvec2 warpB(vec2 t, float k) {\n    vec2 q = 2.0 * t - 1.0;\n    q *= 1.0 + k * (1.0 - q * q);\n    return 0.5 + 0.5 * q;\n}\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    float kB = 0.06 * (1.0 - m) * (1.0 - m);\n    vec2 tb = warpB(tc, kB);\n    vec2 ta = 0.5 + (tc - 0.5) * (1.0 - 0.04 * m * m);     // vi flyver ind i den gamle verden, mens den forlades\n    vec4 a = texture(uA, ta);\n    vec4 b = texture(uB, tb);\n    float la0 = luma(a.rgb), lb0 = luma(b.rgb);\n\n    // lysvægtet log-dybde og middel-lys i området (pixlen selv + NT prøver i en gylden spiral)\n    vec2 px = 1.0 / uRes;\n    float wa = la0 + 2e-3, wb = lb0 + 2e-3;\n    float sa = wa * log(max(a.a, 0.05)), sb = wb * log(max(b.a, 0.05));\n    for (int i = 0; i < NT; i++) {\n        float fi = float(i) + 0.5;\n        float ang = fi * 2.39996;\n        float rr = sqrt(fi / float(NT));\n        vec2 o = vec2(cos(ang), sin(ang)) * rr * RAD * px;\n        float g = 1.0 - 0.5 * rr * rr;                        // svag vægt mod kanten af skiven\n        vec4 ta4 = texture(uA, ta + o);\n        vec4 tb4 = texture(uB, tb + o);\n        float l1 = g * luma(ta4.rgb) + 2e-3, l2 = g * luma(tb4.rgb) + 2e-3;\n        wa += l1; sa += l1 * log(max(ta4.a, 0.05));\n        wb += l2; sb += l2 * log(max(tb4.a, 0.05));\n    }\n    float lsa = sa / wa, lsb = sb / wb;\n    float Las = wa / float(NT + 1), Lbs = wb / float(NT + 1);\n\n    // fronten: eksponentiel fart fra 30 til 0,8 enheder (lige lang tid pr. dybde-oktav)\n    float lr = mix(log(30.0), log(0.8), m);\n    float xa = lsa - lr, xb = lsb - lr;\n    float glob = smoothstep(0.1, 0.9, m);                     // den jævne overtoning, som masken trækkes mod\n    // B findes, hvor dens lys ligger bag fronten; dens nære strukturer toner frem i anden halvdel\n    float presentB = smoothstep(-BB, BB, xb);\n    float ghost = smoothstep(0.3, 0.85, m);\n    // A dækker, hvor områdets lys ligger foran fronten og A dominerer lyset der; opløses som hele former til sidst\n    float dom = smoothstep(0.15, 0.5, Las / (Las + Lbs + 0.01));\n    float occA = (1.0 - smoothstep(-BA, BA, xa)) * dom * (1.0 - smoothstep(0.45, 0.8, m));\n    float w = mix(ghost, 1.0, presentB) * (1.0 - occA) * smoothstep(0.0, 0.12, m);\n    // tomt mørke i begge verdener (kun tåge): jævn overtoning, så der ikke opstår pletter\n    float lit = smoothstep(0.015, 0.12, max(Las, Lbs));\n    w = mix(glob, w, lit);\n    w = mix(w, glob, 0.3);                                    // ingen pixel afgøres helt af én dybdeværdi\n    w = max(w, smoothstep(0.85, 1.0, m));\n\n    vec4 c = mix(a, b, w);\n    // svag kontur i sømfarven på den nye verdens lys, idet fronten når det\n    float band = exp(-xb * xb / (0.5 * BB * BB));\n    float env = smoothstep(0.0, 0.15, m) * (1.0 - smoothstep(0.65, 0.85, m));\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));     // lyse sømfarver (is, syre) dæmpes\n    c.rgb += seam * band * env * 0.3 * w * min(lb0, 1.5);\n    fragColor = c;\n}\n","bloom":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"bloom\": en lotus folder sig ud fra centrum. Tre kranse af mandelformede kronblade (8 store, 8 forskudte,\n// 16 små) vokser fra smalle, let snoede knopper til brede blade, mens kransene drejer langsomt hver sin vej (uBeat/64,\n// uBeat/96, uBeat/48). Den nye verden ses gennem bladene og kommer nærmere, den gamle glider forbi kameraet, som om vi\n// flyver ind gennem blomsten. Hver krans er et lag i sin egen dybde (kalejdoskop-lotus): gennem den ydre ses den nye\n// verden en anelse større, gennem de indre drejet med kransens egen drejning; lagene smelter sammen, før skiftet er\n// færdigt. Bladenes omrids er svage linjer i sømfarven (de indre kun i første halvdel). Ingen lysstyrke følger musikken.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\n#define TAU 6.28318530718\n\n// mandelformet blad (vesica) fra centrum ud til spidsen i afstand L, halv bredde hw; p.x langs bladet, p.y på tværs\nfloat sdPetal(vec2 p, float L, float hw) {\n    float b = max(0.5 * L, 1e-3);\n    hw = clamp(hw, 2e-4, 0.95 * b);\n    vec2 q = vec2(abs(p.y), abs(p.x - b));\n    float d = 0.5 * (b * b / hw - hw);\n    return ((q.y - b) * d > q.x * b) ? length(q - vec2(0.0, b)) : length(q + vec2(d, 0.0)) - (d + hw);\n}\n\n// krans af N blade; a = pixlens vinkel inkl. drejning og snoning; de to nærmeste blade tæller (brede blade overlapper)\nfloat crown(float r, float a, float N, float L, float hw) {\n    float sec = TAU / N;\n    float k = floor(a / sec + 0.5);\n    float d0 = a - k * sec;\n    float d1 = d0 - sign(d0) * sec;\n    return min(sdPetal(r * vec2(cos(d0), sin(d0)), L, hw), sdPetal(r * vec2(cos(d1), sin(d1)), L, hw));\n}\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    float r = max(length(uv), 1e-4), th = atan(uv.y, uv.x);\n    float env = sin(3.14159265 * m);\n    float tw = 0.3 * (1.0 - m) * log(r);            // snoning, der retter sig ud, mens blomsten åbner\n    // forløb: først 8 smalle blade med den gamle verden imellem, så den forskudte krans i hullerne, til sidst\n    // bredes alle blade ud, til blomsten dækker billedet\n    float L = 1.9 * pow(m, 1.7);\n    float wide = mix(0.2, 0.5, smoothstep(0.5, 0.97, m));\n    float L2 = 0.82 * L * smoothstep(0.1, 0.5, m);\n    float L3 = 0.42 * L;\n    float c1 = crown(r, th + tw + TAU * uBeat / 64.0, 8.0, L, L * wide);\n    float c2 = crown(r, th - tw + TAU / 16.0 - TAU * uBeat / 96.0, 8.0, L2, L2 * (wide + 0.03));\n    float c3 = crown(r, th + tw + TAU * uBeat / 48.0, 16.0, L3, L3 * 0.22);\n    float sd = min(min(c1, c2), min(c3, r - 0.12 * L));\n    float e = 0.006 + 0.012 * L;                    // blød kant, vokser med blomsten\n    float w = smoothstep(e, -e, sd) * smoothstep(0.0, 0.05, m);    // ingen prik i centrum ved mix 0+\n    w = max(w, smoothstep(0.9, 1.0, m));\n\n    // flyv-ind: B starter lidt mindre og vokser til fuld størrelse; A forstørres en anelse, mens den forsvinder,\n    // og skubbes blødt udad foran bladkanterne (som en linse), så blomsten presser den gamle verden til side\n    vec2 dir = uv / r;\n    float push = 0.02 * env * exp(-max(sd, 0.0) / 0.07) * smoothstep(-0.02, 0.01, sd);\n    vec2 ta = 0.5 + (tc - 0.5) * (1.0 - 0.07 * m) - dir * push * vec2(uRes.y / uRes.x, 1.0);\n    vec4 a = texture(uA, ta);\n    // kalejdoskop-lotus: hver krans er sit eget lag. Gennem den ydre krans (nærmest) ses den nye verden en anelse\n    // større, gennem den forskudte krans drejet med dens egen drejeretning, og gennem den inderste (fjernest) lidt\n    // mindre og drejet den anden vej. Lagene males bagfra (inderst) og frem, så overgangene er bløde og sammenhængende.\n    float sB = 1.0 + 0.18 * (1.0 - m) * (1.0 - m);\n    float lay = env * (1.0 - smoothstep(0.62, 0.92, m));\n    vec2 d = (tc - 0.5) * vec2(uRes.x / uRes.y, 1.0);    // skærmkoordinater med korrekt aspekt\n    vec2 asp = vec2(uRes.y / uRes.x, 1.0);\n    float an2 = -0.045 * lay, an3 = 0.045 * lay;\n    vec2 tb1 = 0.5 + d * sB * (1.0 - 0.04 * lay) * asp;\n    vec2 tb2 = 0.5 + (mat2(cos(an2), sin(an2), -sin(an2), cos(an2)) * d) * sB * asp;\n    vec2 tb3 = 0.5 + (mat2(cos(an3), sin(an3), -sin(an3), cos(an3)) * d) * sB * (1.0 + 0.03 * lay) * asp;\n    vec4 b1 = texture(uB, 1.0 - abs(1.0 - abs(tb1)));    // spejlet ved kanten (ingen udtværede kantpixels)\n    vec4 b2 = texture(uB, 1.0 - abs(1.0 - abs(tb2)));\n    vec4 b3 = texture(uB, 1.0 - abs(1.0 - abs(tb3)));\n    vec4 b = b1;\n    b = mix(b, b3, smoothstep(e, -e, min(c3, r - 0.12 * L)));\n    b = mix(b, b2, smoothstep(e, -e, c2));\n    b = mix(b, b1, smoothstep(e, -e, c1));\n    // dybde: hvert lag kaster en blød skygge på laget under sig, og hele blomsten på den gamle verden lige uden for\n    // bladkanten, så kronbladene ligger oven på hinanden og svæver foran den gamle verden\n    float k1 = smoothstep(e, -e, c1), k2 = smoothstep(e, -e, c2);\n    float shB = max((1.0 - k1) * smoothstep(0.07, 0.0, c1), (1.0 - k1) * (1.0 - k2) * smoothstep(0.06, 0.0, c2));\n    b.rgb *= 1.0 - 0.3 * lay * shB;\n    a.rgb *= 1.0 - 0.3 * env * smoothstep(0.09, 0.0, sd);\n\n    vec4 c = mix(a, b, w);\n    // omrids: yderkant tydeligst, de indre kranses kanter svagere og kun i første halvdel; kun midt i skiftet\n    float lw = 0.003 + 0.002 * L;\n    float edge = lw * lw / (sd * sd + lw * lw);\n    float in2 = lw * lw / (c2 * c2 + lw * lw) * smoothstep(0.0, -0.03, c1);\n    float in3 = lw * lw / (c3 * c3 + lw * lw) * smoothstep(0.0, -0.03, min(c1, c2));\n    edge *= edge;                                    // smal profil uden brede glorier\n    float inner = max(in2, in3);\n    inner *= inner * (1.0 - smoothstep(0.45, 0.7, m));\n    vec3 seam = uSeam * min(1.0, 0.3 / max(dot(uSeam, vec3(0.2126, 0.7152, 0.0722)), 1e-3));  // lyse sømfarver dæmpes\n    c.rgb += seam * (0.35 * edge + 0.22 * inner) * env;\n    fragColor = c;\n}\n","weave":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"weave\": den nye verden væves ind. To familier af logaritmiske spiraltråde (med og mod uret) krydser\n// hinanden over-under som en kurv, der løber ud fra centrum i takt med beatet (fase-fremdrift, uBeat/16). Trådene\n// er bånd, hvorigennem den nye verden ses; vævet lukker sig først, hvor alle tråde mødes (forsvindingspunktet), og\n// trådene bliver bredere, til vævet er tæt. Hver tråd bølger op og ned mellem krydsningerne: den nye verden ses gennem\n// en tråd, der ligger øverst, en anelse nærmere (parallakse mellem lagene), under-tråden får skygge ved hver\n// krydsning, og den gamle verden bag vævet får en blød skygge langs trådene. Kanterne er tynde linjer i sømfarven,\n// der vokser frem med trådene. Ingen lysstyrke følger musikken.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\n#define TAU 6.28318530718\n#define PI 3.14159265359\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n    vec4 a = texture(uA, tc);\n\n    float r = max(length(uv), 1e-4);\n    float u = log(r), v = atan(uv.y, uv.x) / TAU;\n    const float N = 9.0;                    // arme pr. familie\n    const float K = N / TAU;                // 45 grader mod radius\n    float flow = uBeat / 16.0;\n    float s1 = K * u - flow + N * v;\n    float s2 = K * u - flow - N * v;\n    float f1 = abs(fract(s1) - 0.5), f2 = abs(fract(s2) - 0.5);\n    float aa = 2.0 * K / (r * uRes.y);      // mønstrets frekvens pr. pixel (analytisk, ingen søm ved +-pi)\n    float env = sin(PI * m);\n    float fadeIn = smoothstep(0.0, 0.08, m);\n    // trådenes halve bredde. Vævet lukker sig først, hvor alle tråde mødes: en blød zone om centrum, hvor trådene\n    // bredes helt ud, vokser udad; derfor ses den nye verden først dér, og de tætteste (mindste) masker, der ellers\n    // ville myldre, er allerede lukkede.\n    float h = 0.56 * (1.0 - sqrt(1.0 - m)) - 0.03 * (1.0 - m) + 0.06 * env * exp(-r / 0.3);\n    float Rc = 0.24 * smoothstep(0.12, 0.8, m);\n    h = mix(h, 0.56, smoothstep(0.0, 0.2, m) * smoothstep(Rc + 0.1, Rc - 0.02, r));\n    float hp = max(h, 1e-3);\n    float fine = smoothstep(0.06, 0.22, aa);        // tæt på centrum: tråde for tætte til at vise -> gennemsnit\n    float cov = clamp(2.0 * h + 0.3 * fine * env, 0.0, 1.0);\n    float sw = aa + 0.015;                          // blød kant (relativt til trådafstanden)\n    float w1 = mix(smoothstep(h + sw, h - sw, f1), cov, fine) * fadeIn;\n    float w2 = mix(smoothstep(h + sw, h - sw, f2), cov, fine) * fadeIn;\n    // samlet maske med afrundede hjørner (glat minimum), så de sidste huller lukker som bløde linser, ikke fliser\n    float ga = f1 - h, gb = f2 - h;\n    const float KR = 0.07;\n    float hk = max(KR - abs(ga - gb), 0.0) / KR;\n    float g = min(ga, gb) - hk * hk * KR * 0.25;\n    float w = mix(smoothstep(sw, -sw, g), 1.0 - (1.0 - cov) * (1.0 - cov), fine) * fadeIn;\n    w = max(w, smoothstep(0.9, 1.0, m));\n\n    // over-under: tråd 1 ligger øverst ved krydsninger med ulige floor(s1)+floor(s2). Højden bølger jævnt langs hver\n    // tråd (+1 øverst, -1 under); floor-leddet skifter kun i den anden families mellemrum, hvor tråden ikke findes.\n    float n1 = floor(s1), n2 = floor(s2);\n    float top1 = mod(n1 + n2, 2.0);\n    float H1 = -cos(PI * (s2 - 0.5) + PI * n1);\n    float H2 = cos(PI * (s1 - 0.5) + PI * n2);\n    float t1 = top1 > 0.5 ? w1 : w1 * (1.0 - w2);   // hvor meget af pixlen tråd 1 udgør\n    float t2 = top1 > 0.5 ? w2 * (1.0 - w1) : w2;\n    float sel = (t1 + 0.005) / (t1 + t2 + 0.01);\n    float opn = (1.0 - fine) * (1.0 - smoothstep(0.4, 0.5, h));   // lukket væv: ingen skygger eller lag længere\n    float Hp = mix(H2, H1, sel) * opn;\n    // parallakse: gennem en tråd, der ligger højt, ses den nye verden en anelse nærmere (kun zoom ind -> ingen kantpixels)\n    float par = 0.013 * env * (1.0 - smoothstep(0.7, 0.92, m));\n    vec4 b = texture(uB, 0.5 + (tc - 0.5) * (1.0 - par * (0.5 + 0.5 * Hp)));\n\n    // hvælvede bånd: profilen af den synlige tråd\n    float p1 = sqrt(max(1.0 - (f1 / hp) * (f1 / hp), 0.0));\n    float p2 = sqrt(max(1.0 - (f2 / hp) * (f2 / hp), 0.0));\n    float pt = mix(p2, p1, sel);\n    // skygge på under-tråden lige uden for over-trådens kant\n    float sh = top1 > 0.5 ? w2 * (1.0 - w1) * smoothstep(h + 0.12, h, f1)\n                          : w1 * (1.0 - w2) * smoothstep(h + 0.12, h, f2);\n    float ev = env * opn;\n    b.rgb *= (1.0 - 0.25 * ev * (1.0 - pt)) * (1.0 - 0.35 * ev * sh) * (1.0 - 0.12 * ev * (0.5 - 0.5 * Hp));\n    // den gamle verden bag vævet: blød skygge langs trådene\n    float near = max(smoothstep(h + 0.16, h, f1), smoothstep(h + 0.16, h, f2)) * fadeIn;\n    a.rgb *= 1.0 - 0.3 * ev * near;\n    vec4 c = mix(a, b, w);\n\n    // trådkanter; en kant skjules, hvor den anden tråd ligger ovenpå. Tæt på centrum bliver linjen bredere og\n    // svagere (samme lysmængde), så den aldrig bliver tyndere end ~2,5 pixel; den vokser frem med trådene.\n    float lw = max(0.013, 2.5 * aa);\n    float lamp = 0.013 / lw;\n    float e1 = smoothstep(lw + aa, 0.0, abs(f1 - h)) * (1.0 - (1.0 - top1) * w2);\n    float e2 = smoothstep(lw + aa, 0.0, abs(f2 - h)) * (1.0 - top1 * w1);\n    float grow = smoothstep(-0.01, 0.12, h);        // over ~0,4 s i et 1-takts skift (simuleret: intet spring)\n    vec3 seam = uSeam * min(1.0, 0.3 / max(dot(uSeam, vec3(0.2126, 0.7152, 0.0722)), 1e-3));  // lyse sømfarver dæmpes\n    c.rgb += seam * 0.30 * ev * lamp * grow * max(e1, e2);\n    fragColor = c;\n}\n","marble":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"marble\" (fra brugerens marmorerede maleri \"Liquid Embrace\"): den nye verden flyder ind som marmoreret\n// maling. Et domænevredet marmorfelt (to store sinus-vridninger, der bøjer årerne i brede S-kurver, og tre små, der kun\n// krusér kanten) tegner bugtede årer; langs hver åre svulmer malingen i bløde lapper, der glider langsomt frem ad åren\n// (16 beats pr. bølge). En tærskel, der følger uMix gennem feltets egen fordeling (dækningen vokser jævnt, som uMix^1,3),\n// lader den nye verden komme ind som tynde årer over hele billedet, der svulmer op, flyder sammen til søer og til sidst\n// dækker alt; midten åbner lidt før kanterne, så vi stadig flyver ind i den nye verden. Årerne er som flydende glas:\n// en smal linse-kant, hvor den nye verden bøjes en anelse, en tynd linje i sømfarven, to blanke glansstriber langs\n// formen og en svag indre kontur som i marmorpapir. De ligger oven på den gamle verden med en blød skygge (kun når\n// malingen er mindst lige så lys som bunden). Mønstret flyder og drejer langsomt (uBeat/16), ånder over 8 beats og\n// røres en anelse rundt om midten, mens den nye verden kommer ind. Ingen lysstyrke følger musikken.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\n#define PI 3.14159265359\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nvec2 mirror(vec2 t) { return 1.0 - abs(1.0 - abs(t)); }       // spejlet ved kanten (ingen udtværede kantpixels)\n\n// feltets fordeling (middel over 121 tidspunkter i et 3000-beats sæt, med omrøringen ved det tilhørende mix):\n// tærsklen, der dækker andelen cov af billedet\nconst float QT[21] = float[21](0.000, 0.058, 0.115, 0.172, 0.227, 0.281, 0.334, 0.384, 0.431, 0.475, 0.516,\n                               0.551, 0.582, 0.610, 0.640, 0.672, 0.711, 0.755, 0.803, 0.856, 0.976);\nfloat thresh(float m) {\n    float x = clamp(m, 0.0, 1.0) * 20.0;\n    float i = min(floor(x), 19.0);\n    int k = int(i);\n    return mix(QT[k], QT[k + 1], x - i);\n}\n\n// marmorfeltet i punktet p (skærmhøjde-enheder, |p| = afstand til midten). F: 0 midt i en åre, stiger ud mod den gamle\n// verden. grad: dF/dp (analytisk via Jacobi-matricen gennem vridningerne). disp: de store vridningers forskydning.\nfloat marble(vec2 p, float ph, float br, float lob, out vec2 grad, out vec2 disp) {\n    const float S = 1.8;\n    vec2 q = p * S + vec2(0.3, -0.2);\n    vec2 q0 = q;\n    vec2 jx = vec2(S, 0.0), jy = vec2(0.0, S);      // gradienterne af q.x og q.y\n    disp = vec2(0.0);\n    for (int i = 1; i <= 5; i++) {\n        float fi = float(i);\n        if (i == 3) disp = (q - q0) / S;             // væske-bølgen bruger kun de to store vridninger (glat, ingen takker)\n        // de to store vridninger former årerne (brede S-kurver); de små falder hurtigt af (1/i^2), så de kun kruser\n        // kanten og aldrig kammer malingen til hårnåle-zigzag\n        float a = (i <= 2 ? 0.85 / fi : 0.9 / (fi * fi)) * (1.0 + 0.05 * sin(br + 1.3 * fi));  // åndedræt, 8 beats\n        float k1 = 1.25 * fi;\n        float ar = k1 * q.y + ph * (0.55 + 0.17 * fi) + 1.7 * fi;\n        q.x += a * sin(ar);\n        jx += a * cos(ar) * k1 * jy;\n        float k2 = 1.05 * fi;\n        ar = k2 * q.x - ph * (0.45 + 0.13 * fi) + 2.3 * fi;\n        q.y += a * sin(ar);\n        jy += a * cos(ar) * k2 * jx;\n    }\n    // årerne: nulpunkterne af en vredet sinus (kontinuerte kurver, der aldrig ender i en spids)\n    const vec2 dv = vec2(0.6, 0.8);\n    float phi = 3.0 * dot(dv, q);\n    vec2 gphi = 3.0 * (dv.x * jx + dv.y * jy);\n    float s = sin(phi);\n    float v = abs(s);\n    vec2 gv = sign(s) * cos(phi) * gphi;\n    // årens bredde: lapper langs åren (samme bølgelængde på tværs og langs, så de sidste øer af den gamle verden bliver\n    // runde), en svag, stor region og midten først\n    const vec2 dp = vec2(-0.8, 0.6);\n    float chi = 2.6 * dot(dp, q) + lob;\n    vec2 gchi = 2.6 * (dp.x * jx + dp.y * jy);\n    float psi = 0.8 * q.y - 0.5 * q.x + 0.9;\n    vec2 gpsi = 0.8 * jy - 0.5 * jx;\n    float r2 = dot(p, p);\n    float rad = r2 / (r2 + 0.3);\n    vec2 grad2 = p * (0.6 / ((r2 + 0.3) * (r2 + 0.3)));\n    float M = 0.68 + 0.15 * cos(chi) + 0.04 * sin(psi) + 0.14 * rad;\n    vec2 gM = -0.15 * sin(chi) * gchi + 0.04 * cos(psi) * gpsi + 0.14 * grad2;\n    grad = M * gv + v * gM;\n    return v * M;\n}\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    vec2 asp = vec2(uRes.y / uRes.x, 1.0);           // skærmhøjde-enheder -> teksturkoordinater\n    float env = sin(PI * m);\n\n    // langsom drejning med beatet (uBeat/16) + en omrøring om midten, der vokser med skiftet\n    float t16 = uBeat / 16.0;\n    float r2 = dot(uv, uv);\n    float tw = 0.6 * m * exp(-r2 / 0.4);\n    float ang = 0.12 * t16 + tw;\n    float ca = cos(ang), sa = sin(ang);\n    vec2 p = mat2(ca, sa, -sa, ca) * uv;\n    vec2 gp, disp;\n    float F = marble(p, 0.7 * t16, 2.0 * PI * uBeat / 8.0, 2.0 * PI * t16, gp, disp);\n    disp = disp * mat2(ca, sa, -sa, ca);             // drejer med mønstret\n    // gradient i skærmkoordinater: dp/duv = R + (R' uv) x grad(ang)\n    vec2 gang = tw * (-2.0 / 0.4) * uv;\n    vec2 guv = gp * mat2(ca, sa, -sa, ca) + gang * dot(gp, vec2(-p.y, p.x));\n    float gl = length(guv);\n    vec2 nOut = guv / max(gl, 1e-4);                 // peger ud af åren (mod den gamle verden)\n\n    // tærsklen: jævn dækning; lidt under minimum i starten (ingen prik ved mix 0+) og blødt over maksimum til sidst\n    // (de sidste øer af den gamle verden svinder i samme tempo som resten); dækningen følger m^1,3: de tynde årer får\n    // lidt længere tid, før de flyder sammen\n    float cov = pow(m, 1.3);\n    float T = thresh(cov) - 0.06 * (1.0 - smoothstep(0.0, 0.06, m)) + 0.05 * smoothstep(0.8, 1.0, m);\n    float sd = (F - T) / max(gl, 0.5);               // afstand til årens kant (skærmhøjder), < 0 inde i åren\n    const float E = 0.007;                           // blød kant\n    float w = smoothstep(E, -E, sd);\n    // tætte folder (årernes afstand under ~2 % af højden): masken går over i dækningen, så hårfine striber ikke flimrer\n    float fine = smoothstep(70.0, 150.0, gl);\n    w = mix(w, cov, fine) * smoothstep(0.0, 0.03, m);\n    w = max(w, smoothstep(0.93, 1.0, m));\n\n    // væske: den gamle verden bølger mere og mere (kun de store vridninger: glat, ingen takker); den nye verden starter\n    // en anelse forstørret og bølget og falder til ro (alle opslag inden for billedet)\n    float sv = env * (1.0 - fine);\n    vec2 ta = 0.5 + (tc - 0.5) * (1.0 - 0.04 * m) + disp * 0.016 * smoothstep(0.0, 0.6, m) * asp;\n    float mb = (1.0 - m) * (1.0 - m);\n    vec2 tb = 0.5 + (tc - 0.5) * (1.0 - 0.06 * mb) + disp * 0.014 * mb * asp;\n    // linse-kant: inden for 0,02 fra kanten bøjes den nye verden en anelse (som kanten af en dråbe flydende glas)\n    float bev = 1.0 - clamp(-sd / 0.02, 0.0, 1.0);\n    tb += nOut * (0.004 * bev * bev * sv) * asp;\n    vec4 a = texture(uA, mirror(ta));\n    vec4 b = texture(uB, mirror(tb));\n\n    // malingens læbe: lys skråt fra oven; den side, der vender væk, får en smal skygge, den gamle verden en blød\n    // skygge uden for kanten (årerne ligger oven på den) - kun så meget, som malingen er lys i forhold til bunden,\n    // så mørke nye verdener ikke bliver sorte huller\n    const vec2 L2 = vec2(-0.5433, 0.8395);\n    float facing = dot(nOut, L2);\n    float dsh = (sd + 0.006) / 0.006;\n    b.rgb *= 1.0 - 0.3 * sv * exp(-dsh * dsh) * max(-facing, 0.0);\n    float cast_ = clamp(luma(b.rgb) / (luma(a.rgb) + 1e-3), 0.3, 1.0);\n    a.rgb *= 1.0 - 0.28 * cast_ * sv * exp(-max(sd, 0.0) / 0.03) * (0.6 + 0.4 * max(-facing, 0.0))\n                 * smoothstep(-0.006, 0.004, sd);\n\n    vec4 c = mix(a, b, w);\n\n    // den blanke søm: tynd kantlinje, vådt glansskær på den lyse side af læben, en svagere glansstribe længere inde\n    // (som maleriets striber langs formerne) og en svag indre kontur (marmorpapir)\n    float px = 1.0 / uRes.y;\n    float lw = 1.6 * px;\n    float edge = lw * lw / (sd * sd + lw * lw);\n    float dg = (sd + 0.0045) / 0.0035;\n    float fpos = max(facing, 0.0);\n    float gloss = exp(-dg * dg) * fpos * fpos;\n    float dg2 = (sd + 0.012) / 0.0022;\n    float gloss2 = exp(-dg2 * dg2) * (0.25 + 0.75 * fpos) * w * (1.0 - smoothstep(0.6, 0.85, m));\n    float si = sd + 0.024;\n    float inner = lw * lw / (si * si + lw * lw) * w * (1.0 - smoothstep(0.5, 0.8, m));\n    float dense = smoothstep(110.0, 50.0, gl);      // tætte folder: ingen linjer (intet flimmer)\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));   // lyse sømfarver dæmpes\n    float vis = env * smoothstep(0.0, 0.04, m);\n    c.rgb += seam * (0.3 * edge + 0.6 * gloss + 0.22 * gloss2 + 0.12 * inner) * dense * vis;\n    fragColor = c;\n}\n","prism":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"prism\" (fra prisme-krystallerne, der svæver om mixer-katten i brugerens film): en sværm af store,\n// tumlende krystaller (dobbelte pyramider) hvirvler gennem billedet. Hver krystal er et vindue ind til den nye verden,\n// set brudt gennem glasset: hver facet viser B en anelse forskudt og forstørret efter facettens hældning, så B ses\n// som en slebet juvel, og de stejle facetter spejler en svag rest af den gamle verden. Krystallerne bliver flere,\n// større og hvirvler udad, mens en stor krystal i midten nærmer sig og til sidst fylder billedet; brydningen retter\n// sig ud, og B står hel. Kanterne er tynde linjer i sømfarven med konstant lys, splittet spektralt (på silhuetten\n// ligger sømfarvens røde del lidt udenfor og den blå lidt indenfor, som kanten af et prisme), B's røde og blå kanal\n// spredes en anelse nær kanterne, glasset lyser svagt langs kanterne indefra, og bagkanterne anes gennem glasset. Krystallerne er strålesporede i en lille 3D-scene (smal synsvinkel, kameraet altid uden for glasset):\n// strålen giver facetten og om pixlen er inde i krystallen; kanterne er krystallens 12 kanter projiceret på skærmen,\n// og hver kant er forkant, silhuet eller bagkant efter, hvor mange af dens to flader der vender mod kameraet (blødt\n// over et par grader, så intet springer, når en flade vender). Krystallerne gennemløbes forfra og bagud; den første,\n// strålen rammer, dækker resten. Den gamle verden og krystallerne bagved får en blød skygge og en smal mørk kontur lige\n// uden for silhuetten, og den gamle verden et linseskub uden for krystallerne. Ingen lysstyrke følger musikken (facetternes\n// lys og spejling regnes fra drejningen uden kick-rykket); uBeat driver kun tumlen og hvirvlen og giver på\n// hvert beat (kicket) sværmen et kort, sprødt ryk i drejningen og et lille skub udad, der giver efter over beatet\n// (den store krystal kun et lille drej, så B's areal ikke pumper med kicket).\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\n#define TAU 6.28318530718\n#define PI 3.14159265359\nconst int N = 9;                 // krystaller: 1..8 = sværmen (forfra og bagud), 0 = den store i midten (bagerst)\nconst float F = 2.4;             // brændvidde (skærmhøjde-enheder): smal synsvinkel\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nvec2 mirror(vec2 t) { return 1.0 - abs(1.0 - abs(t)); }       // spejlet ved kanten (ingen udtværede kantpixels)\nfloat hash(float n) { return fract(sin(n * 127.1 + 11.7) * 43758.5453); }\nfloat lor(float x, float w) { return w * w / (x * x + w * w); }\nfloat lor2(float x, float w) { float l = lor(x, w); return l * l; }   // smal linjeprofil\n\nmat3 rotAxis(vec3 a, float ang) {\n    float c = cos(ang), s = sin(ang), k = 1.0 - c;\n    return mat3(c + a.x * a.x * k, a.y * a.x * k + a.z * s, a.z * a.x * k - a.y * s,\n                a.x * a.y * k - a.z * s, c + a.y * a.y * k, a.z * a.y * k + a.x * s,\n                a.x * a.z * k + a.y * s, a.y * a.z * k - a.x * s, c + a.z * a.z * k);\n}\n\n// ryk pr. beat: på ~2 frames, giver efter over resten af beatet (0 ved begge ender)\nfloat jolt(float ph) { return (1.0 - exp(-ph * 20.0)) * exp(-ph * 5.0); }\nfloat JL;                        // beat-rykket i dette billede (sat i main)\n\n// krystal i: projiceret midte c (skærmhøjder), projiceret radius s, dybde z og strækning el langs den lokale z-akse\nvoid place(int i, float m, out vec2 c, out float s, out float z, out float el) {\n    float fi = float(i);\n    if (i == 0) {\n        // den store krystal: dukker op i midten, nærmer sig og fylder til sidst billedet\n        c = vec2(0.04, -0.02) * (1.0 - m);\n        s = smoothstep(0.1, 0.32, m) * (0.12 + 1.7 * pow(smoothstep(0.2, 0.93, m), 1.4));\n        z = 9.0;\n        el = 1.15;\n    } else {\n        float h1 = hash(fi * 3.17 + 1.3), h2 = hash(fi * 5.71 + 2.1), h4 = hash(fi * 9.13 + 5.2);\n        float a0 = 0.015 + (fi - 1.0) * 0.045;                  // sværmen bliver flere: én ny krystal ad gangen\n        float ang = fi * 2.39996 + 0.7 + 0.9 * m + TAU * uBeat / 192.0;\n        float rho = (0.34 + 0.36 * h1) * (0.7 + 1.2 * m) * (1.0 + 0.025 * JL);   // hvirvler udad, mens de nærmer sig\n        c = rho * vec2(cos(ang), sin(ang));\n        s = (0.11 + 0.08 * h2) * smoothstep(a0, a0 + 0.15, m) * (1.0 + 0.7 * m * m);\n        z = 4.0 + 0.25 * fi;                                     // fast dybde-rækkefølge: 1 forrest, 8 bagerst\n        el = 1.2 + 0.45 * h4;                                    // let aflange dobbelte pyramider\n    }\n}\n\n// krystallens drejning (lokal -> verden): tumler om sin egen akse, med beatet og gennem skiftet; jl = kick-rykket\n// (geometrien får det; lyset regnes fra drejningen uden ryk, så ingen facet skifter lys på kicket)\nmat3 spin(int i, float m, float jl) {\n    float fi = float(i);\n    float h1 = hash(fi * 3.17 + 1.3), h2 = hash(fi * 5.71 + 2.1), h3 = hash(fi * 7.33 + 0.4);\n    float h4 = hash(fi * 9.13 + 5.2), h5 = hash(fi * 11.7 + 3.3);\n    vec3 ax = normalize(vec3(h3 - 0.5, h4 - 0.5, h5 - 0.5) + vec3(0.21, 0.13, 0.05));\n    float dir = h2 > 0.5 ? 1.0 : -1.0;\n    return i == 0 ? rotAxis(ax, TAU * h1 + dir * (TAU * uBeat / 96.0 + 2.0 * m + 0.04 * jl))\n                  : rotAxis(ax, TAU * h5 + dir * (TAU * uBeat / 40.0 + 2.2 * m + 0.14 * jl));\n}\n\nvec2 proj(vec3 w) { return F * w.xy / w.z; }\n\n// én kant A-B mellem to flader med \"vender mod kameraet\" pa, pb: silhuet-afstand, nærmeste for-/silhuetkant og linjer\nfloat LW, SP, LR, INS;           // linjebredde, spektral-split, linjernes rækkevidde, +1/-1 = pixlen inde i/uden for krystallen\nvec3 spec(float x) { return vec3(lor2(x + SP, LW), lor2(x, LW), lor2(x - SP, LW)); }\nvoid edge(vec2 p, vec2 A, vec2 B, float pa, float pb,\n          inout float dSil, inout float dFr, inout vec2 nFr, inout vec3 lF, inout float lB) {\n    vec2 q = p - A, ba = B - A;\n    float h = clamp(dot(q, ba) / max(dot(ba, ba), 1e-9), 0.0, 1.0);\n    vec2 r = q - ba * h;\n    float ax = length(r);\n    float wF = pa * pb, wS = pa + pb - 2.0 * pa * pb, wK = (1.0 - pa) * (1.0 - pb);\n    if (wS > 0.5) dSil = min(dSil, ax);\n    if (wF + wS > 0.5 && ax < dFr) { dFr = ax; nFr = r / max(ax, 1e-7); }\n    if (ax < LR) {\n        // spektralt splittet linje + en svag glorie. Silhuetten: sømfarvens røde del ligger lidt udenfor, den blå\n        // lidt indenfor (som kanten af et prisme); forkanterne: fast side efter kantens retning\n        float xi = ax * (ba.x * q.y - ba.y * q.x >= 0.0 ? 1.0 : -1.0);\n        // (glorien er smal (lor2): 12 kanters brede 1/x²-haler fyldte små krystaller op med sømfarve)\n        lF += 0.3 * (wF * spec(xi) + wS * spec(ax * INS)) + (wF + wS) * 0.06 * lor2(ax, 4.0 * LW);\n        lB += wK * lor2(ax, LW);\n    }\n}\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    vec2 asp = vec2(uRes.y / uRes.x, 1.0);\n    float px = 1.0 / uRes.y;\n    vec3 d = vec3(uv, F);                                        // stråle (ikke normeret)\n    LW = 2.6 * px; SP = 4.0 * px; LR = 48.0 * px;\n    JL = jolt(fract(uBeat)) * smoothstep(0.02, 0.12, m) * (1.0 - smoothstep(0.7, 0.92, m));\n\n    float sMax = -1e3;                                           // fortegnsafstand til nærmeste silhuet (> 0 inde)\n    int prim = -1;\n    vec3 nP = vec3(0.0, 0.0, -1.0);                              // facettens normal (den ramte krystal)\n    vec3 nL = nP;                                                // samme normal uden kick-rykket (lys, Fresnel)\n    vec2 cP = vec2(0.0), eNP = vec2(1.0, 0.0);\n    float dEP = 1e3, dSP = 0.0, ampP = 0.0;\n    vec3 lines = vec3(0.0);\n\n    for (int k = 0; k < N; k++) {\n        int i = k + 1 < N ? k + 1 : 0;                           // forfra og bagud: sværmen, så den store krystal\n        vec2 c; float s, z, el;\n        place(i, m, c, s, z, el);\n        if (s < 1e-4) continue;\n        float R = s * z / F;\n        // billig afgrænsning: den projicerede omskrevne kugle (+ margen til skygge og linjer)\n        float rb = R * el / z;\n        float bound = F * rb / sqrt(max(1.0 - rb * rb, 1e-3)) * (1.0 + dot(c, c) / (F * F)) + 0.12;\n        if (dot(uv - c, uv - c) > bound * bound) continue;\n\n        mat3 M = spin(i, m, JL);\n        vec3 sc = vec3(1.0, 1.0, el);\n        vec3 P = vec3(c * z / F, z);\n        mat3 Mt = transpose(M);\n        vec3 ol = Mt * (-P) / R;                                 // kameraet i krystallens enhedsrum\n        vec3 dl = Mt * d / R;\n        // strålen mod de 4 slabs |n.p| <= 1 (n = fortegn / sc): ind- og udgang og indgangsfacettens normal\n        float tIn = -1e9, tOut = 1e9;\n        vec3 nIn = vec3(0.0, 0.0, -1.0);\n        for (int j = 0; j < 4; j++) {\n            vec3 sg = j == 0 ? vec3(1.0, 1.0, 1.0) : j == 1 ? vec3(1.0, 1.0, -1.0) : j == 2 ? vec3(1.0, -1.0, 1.0) : vec3(-1.0, 1.0, 1.0);\n            vec3 n = sg / sc;\n            float nd = dot(n, dl), no = dot(n, ol);\n            nd = abs(nd) < 1e-7 ? 1e-7 : nd;\n            float t1 = (-1.0 - no) / nd, t2 = (1.0 - no) / nd;\n            float ta = min(t1, t2);\n            if (ta > tIn) { tIn = ta; nIn = -sign(nd) * (M * n); }\n            tOut = min(tOut, max(t1, t2));\n        }\n        bool hit = tIn < tOut;\n\n        // fladernes retning: flade (sx,sy,sz) vender mod kameraet, når kameraet ligger uden for dens plan; blødt over\n        // ~3 grader (fladen ses da på kant, og dens kanter falder sammen, så kanttypen glider uden spring)\n        vec3 q = ol / sc;\n        float iq = 1.0 / max(length(q), 1e-4);\n        float f[8];                                              // indeks: bit0 = x, bit1 = y, bit2 = z (0 = +, 1 = -)\n        for (int j = 0; j < 8; j++) {\n            vec3 sg = vec3((j & 1) == 0 ? 1.0 : -1.0, (j & 2) == 0 ? 1.0 : -1.0, (j & 4) == 0 ? 1.0 : -1.0);\n            f[j] = smoothstep(-0.05, 0.05, (dot(sg, q) - 1.0) * iq);\n        }\n        // de 6 hjørner projiceret på skærmen og de 12 kanter: X-Y (fladerne +-z), X-Z (+-y), Y-Z (+-x)\n        vec3 ex = M[0] * R, ey = M[1] * R, ez = M[2] * (R * el);\n        vec2 X0 = proj(P + ex), X1 = proj(P - ex), Y0 = proj(P + ey), Y1 = proj(P - ey), Z0 = proj(P + ez), Z1 = proj(P - ez);\n        float dSil = 1e3, dFr = 1e3;\n        vec2 nFr = vec2(1.0, 0.0);\n        vec3 lF = vec3(0.0);\n        float lB = 0.0;\n        INS = hit ? 1.0 : -1.0;\n        edge(uv, X0, Y0, f[0], f[4], dSil, dFr, nFr, lF, lB);\n        edge(uv, X1, Y0, f[1], f[5], dSil, dFr, nFr, lF, lB);\n        edge(uv, X0, Y1, f[2], f[6], dSil, dFr, nFr, lF, lB);\n        edge(uv, X1, Y1, f[3], f[7], dSil, dFr, nFr, lF, lB);\n        edge(uv, X0, Z0, f[0], f[2], dSil, dFr, nFr, lF, lB);\n        edge(uv, X1, Z0, f[1], f[3], dSil, dFr, nFr, lF, lB);\n        edge(uv, X0, Z1, f[4], f[6], dSil, dFr, nFr, lF, lB);\n        edge(uv, X1, Z1, f[5], f[7], dSil, dFr, nFr, lF, lB);\n        edge(uv, Y0, Z0, f[0], f[1], dSil, dFr, nFr, lF, lB);\n        edge(uv, Y1, Z0, f[2], f[3], dSil, dFr, nFr, lF, lB);\n        edge(uv, Y0, Z1, f[4], f[5], dSil, dFr, nFr, lF, lB);\n        edge(uv, Y1, Z1, f[6], f[7], dSil, dFr, nFr, lF, lB);\n        float amp = smoothstep(0.01, 0.08, s);\n        lines += amp * lF;\n        if (!hit) {\n            if (-dSil > sMax) { sMax = -dSil; cP = c; }          // linseskubbet regnes fra den nærmeste silhuet\n            continue;\n        }\n        // ramt: denne krystal dækker alle krystaller bag sig\n        lines += amp * 0.08 * lB * vec3(1.0);\n        prim = i; nP = normalize(nIn); cP = c; eNP = nFr; dEP = dFr; dSP = dSil; ampP = amp;\n        nL = normalize(spin(i, m, 0.0) * (Mt * nIn));            // samme facet, uden kick-rykket: til lys og spejling\n        break;\n    }\n\n    float env = sin(PI * m);\n    float fx = 1.0 - smoothstep(0.72, 0.97, m);                 // brydningen retter sig ud til sidst\n    float aa = 1.5 * px;\n    float sIn = prim >= 0 ? dSP : sMax;\n    float wS = smoothstep(-aa, aa, sIn);                         // B-masken: pixlen ligger i en krystal\n    float fill = smoothstep(0.8, 1.0, m);\n    float outD = max(-sMax, 0.0);                                // afstand til nærmeste krystal foran (eller ved siden af)\n\n    // den gamle verden: vi flyver en anelse ind i den; skubbes blødt væk fra krystallernes kanter og får en blød skygge\n    vec2 pdir = normalize(uv - cP + vec2(1e-5));\n    float push = 0.014 * env * exp(-outD / 0.04) * (1.0 - wS);\n    vec2 ta = 0.5 + (tc - 0.5) * (1.0 - 0.05 * m) - pdir * push * asp;\n    vec4 a = texture(uA, mirror(ta));\n    // skyggen: en blød (~3 % af skærmhøjden) og en smal, mørk kontur (~6 px) lige uden for silhuetten, så krystallen\n    // står skarpt mod en travl, lys gammel verden (geometri, intet lys der følger musikken)\n    float shade = env * (0.24 * exp(-outD / 0.03) + 0.34 * exp(-outD / 0.006));\n    a.rgb *= 1.0 - shade * (1.0 - wS);\n\n    // den nye verden uden for krystallerne (kun til den sidste udfyldning): starter lidt mindre og vokser til fuld størrelse\n    float sB = 1.0 + 0.15 * (1.0 - m) * (1.0 - m);\n    vec4 b = texture(uB, mirror(0.5 + (tc - 0.5) * sB));\n    float lam = dot(nL, normalize(vec3(-0.45, 0.65, -0.6)));    // facettens lys (fra oven til venstre), uden kick-ryk\n    if (wS > 0.0) {\n        // gennem facetten: forskudt efter facettens hældning, forstørret og en anelse drejet om krystallens midte\n        // (en slebet juvel: hver facet viser B fra sin egen vinkel)\n        vec2 off = -0.085 * nP.xy;\n        float mag = -0.10 + 0.07 * nP.z;                        // nP.z < 0: facetten vender mod kameraet\n        float rf = 0.1 * fx * dot(nP.xy, vec2(0.8, -0.6));\n        vec2 rel = uv - cP;\n        rel = mat2(cos(rf), sin(rf), -sin(rf), cos(rf)) * rel * (1.0 + fx * mag);\n        vec2 tbf = 0.5 + ((cP + rel) * sB + fx * off) * asp;\n        // svag spektral spredning nær kanterne: B's røde og blå kanal hentes en anelse til hver side af kanten\n        float disp = 0.005 * fx * exp(-dEP / 0.03);\n        vec4 bF = texture(uB, mirror(tbf));\n        bF.r = texture(uB, mirror(tbf + eNP * disp * asp)).r;\n        bF.b = texture(uB, mirror(tbf - eNP * disp * asp)).b;\n        bF.rgb *= 1.0 + 0.3 * fx * lam;                         // drejer langsomt med krystallen\n        // glasset spejler en svag rest af den gamle verden i de stejle facetter (Fresnel)\n        float fres = (1.0 - smoothstep(0.5, 0.85, m)) * (0.05 + 0.3 * pow(1.0 - abs(nL.z), 3.0));\n        vec3 aRef = texture(uA, mirror(0.5 + (uv * 0.92 + 0.12 * nP.xy) * asp)).rgb;\n        bF.rgb = mix(bF.rgb, aRef, fres);\n        // en krystal længere fremme kaster en blød skygge på krystallen bagved\n        if (prim >= 0) bF.rgb *= 1.0 - shade;\n        b = mix(b, bF, wS);\n    }\n    vec4 col = mix(a, b, max(wS, fill));\n\n    // lys i sømfarven (fast, følger kun krystallernes form): kanterne (ovenfor), et svagt kantlys i glasset langs\n    // silhuetten og forkanterne, en svag glastone på hver facet og en svag glans på de facetter, der vender mod lyset\n    if (prim >= 0) {\n        float dIn = max(dSP, 0.0);\n        float l2 = max(lam, 0.0);\n        // (et smalt kantlys og kun en meget svag flade-tone: glasset skal være klart, så B ses tydeligt indeni, og\n        // krystallen tegnes af sine kanter, ikke af en farvet fyldning)\n        lines += ampP * fx * (0.05 * exp(-dIn / 0.012) + 0.012 * exp(-dIn / 0.05) + 0.02 * exp(-dEP / 0.012)\n                              + 0.008 * (0.6 + 0.4 * lam) + 0.02 * l2 * l2);\n    }\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));   // lyse sømfarver dæmpes\n    float vis = smoothstep(0.0, 0.05, m) * (1.0 - smoothstep(0.75, 0.97, m));\n    col.rgb += seam * lines * vis;\n    fragColor = col;\n}\n","shutter":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"shutter\" (hard techno): en tung rulleport af stål går ned over den gamle verden og bærer den nye\n// verden på sine lameller. Porten kører ned i hak, låst til beatet: motoren blander med uMix = smoothstep(x), hvor x\n// er tiden lineært over 1 takt (drop) eller 8 takter, og x = 0, 1/4, 2/4, 3/4 ligger derfor altid på et beat. Ved\n// hvert af de fire tidspunkter udløses et hak: 60 % af hakkets vej falder på ~6 frames, resten glider jævnt (1 takt:\n// fire hak, ét pr. kick; 8 takter: et tungt hak hver anden takt; den jævne rest holder lysskiftet pr. frame nede).\n// Imellem giver hvert beat (uBeat) et lille ryk ned, der fjedrer tilbage, lamellerne rasler sidelæns, og den gamle\n// verden presses en anelse ned. Fra 3. hak (x = 3/4, uMix = 0,84375) styrter porten accelererende i gulvet og stopper\n// brat: et kort dunk, hvor den nye verden sætter sig mod gulvet og lamellerne trykkes sammen; resten af sidste beat\n// lukker slidserne, og riller og bundskinne smelter ind i den nye verden, som står alene på næste downbeat. Nederst en tung bundskinne med skråstriber; lamellerne har rækker af ventilationsslidser, et\n// svagt, konstant stålskær og en rille/læbe ved hvert led. Ingen lysstyrke følger musikken.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nfloat hash11(float n) { return fract(sin(n * 127.1 + 11.7) * 43758.5453); }\n\n// ryk pr. beat: ned på ~2 frames, fjedrer tilbage over resten af beatet (0 ved begge ender)\nfloat jolt(float ph) { return (1.0 - exp(-ph * 20.0)) * exp(-ph * 5.0); }\n// den omvendte smoothstep: overgangens tid lineært (x = k/4 ligger på et beat ved både 4 og 32 beats)\nfloat unsmooth(float m) { return 0.5 - sin(asin(1.0 - 2.0 * m) / 3.0); }\n// et hak: falder med fuld fart fra starten og bremser op inden for w af hakkets tid\nfloat notch(float f, float w) { float t = 1.0 - clamp(f / w, 0.0, 1.0); return 1.0 - t * t; }\n\nconst float R = 0.05;                        // bundskinnens højde\nconst float P = 0.085;                       // lamel-afstand\nconst float K = 0.6;                         // andel af hvert hak, der falder på slaget (resten glider jævnt)\nconst float W = 0.25;                        // hakkets varighed (andel af hakkets tid)\nconst float WL = 0.22;                       // landingens varighed: porten styrter i gulvet og stopper brat\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    float asp = uRes.x / uRes.y;\n    float px = 1.0 / uRes.y;                 // én (supersamplet) pixel i skærmhøjde-enheder\n    float y = 1.0 - tc.y;                    // 0 = øverst\n    float x = (tc.x - 0.5) * asp;\n\n    float xt = unsmooth(m);\n    float j = min(floor(xt * 4.0), 3.0);     // hak nr. 0..3 (3 = landingen)\n    float f = xt * 4.0 - j;\n    float ur = (j + (j > 2.5 ? pow(min(f / WL, 1.0), 1.25) : mix(f, notch(f, W), K))) * 0.25;\n    float env = smoothstep(0.02, 0.12, xt) * (1.0 - smoothstep(0.62, 0.73, xt));\n    float jl = jolt(fract(uBeat)) * env;\n    // bundkanten: tung port, hvis hak bliver længere og længere; lander på gulvet (y = 1) og bliver der\n    float yb0 = -0.012 + 1.012 * pow(ur, 1.35);\n    float yb = min(yb0 + 0.045 * jl, 1.0);\n    float d = yb - y;                        // > 0 inde i porten (afstand op fra bundkanten)\n    // landingen: dunket topper, idet porten rammer gulvet, og er væk inden næste downbeat\n    float tq = clamp(xt * 4.0 - 3.0, 0.0, 1.0);\n    float tc2 = max(tq - WL, 0.0);           // tid siden porten ramte gulvet\n    float th = (1.0 - exp(-tc2 * 60.0)) * exp(-tc2 * 9.0) * (1.0 - tq);\n    float close = smoothstep(WL, 0.8, tq);   // porten står på gulvet: slidser lukker, lameller smelter sammen\n    float fuse = 1.0 - close;\n\n    // den gamle verden: presses en anelse ned mod gulvet af porten (dybde: fjern verden, nær port) og ryster på slaget\n    float za = (0.004 + 0.02 * ur) * smoothstep(0.0, 0.1, xt);\n    vec2 ta = vec2(0.5, 0.0) + (tc - vec2(0.5, 0.0)) * (1.0 - za);\n    vec4 a = texture(uA, vec2(ta.x, ta.y + 0.004 * jl));\n\n    float aa = 1.6 * px;\n    float inC = smoothstep(-aa, aa, d);\n    float inRail = inC * (1.0 - smoothstep(R - aa, R + aa, d));\n\n    // lameller over skinnen; når porten lander, trykkes de sammen (de øverste lameller synker efter)\n    float ds = d - R;\n    float Pc = P * (1.0 - 0.05 * th - 0.06 * close);\n    float fi = floor(ds / Pc);\n    float f2 = fract(ds / Pc);               // 0 = lamellens underkant, 1 = overkant\n    float fa = aa / Pc;\n\n    // den nye verden sidder på porten og kører med ned (delvis parallakse) og står stille, når porten er nede;\n    // på slaget rasler lamellerne sidelæns (skjult i rillen); dunket trykker den nye verden mod gulvet\n    float off = 0.3 * max(1.0 - yb, 0.0);\n    float rattle = (hash11(fi) - 0.5) * 0.014 * jl * step(0.0, ds);\n    float yB = 1.0 - (1.0 - y - off) * (1.0 - 0.03 * th);\n    float xB = 0.5 + (tc.x - 0.5) * (1.0 - 0.008 * env) + rattle;   // margen: raslen henter aldrig uden for billedet\n    vec4 b = texture(uB, vec2(xB, 1.0 - clamp(yB, 0.0, 1.0)));\n    // ventilationsslidser: en række korte slidser i lamellens øvre del, forskudt hver anden lamel\n    float sh = 0.075 * fuse;                 // slidsens halve højde (i lamel-enheder)\n    float sy = smoothstep(sh + fa, sh - fa, abs(f2 - 0.78));\n    float sx = fract(x / 0.16 + 0.5 * mod(fi, 2.0));\n    float sxm = smoothstep(0.08 - aa / 0.16, 0.08 + aa / 0.16, sx) * smoothstep(0.92 + aa / 0.16, 0.92 - aa / 0.16, sx);\n    float slot = sy * sxm * step(0.0, ds) * inC * fuse;   // (fuse: ingen hårstreg tilbage, når slidsen er lukket)\n\n    // lamellens profil: hvælvet flade, mørk rille ved leddet, skygge under læben fra lamellen ovenover\n    float jd = min(f2, 1.0 - f2) * Pc;       // afstand til nærmeste led\n    float pr = abs(2.0 * f2 - 1.0);\n    float prof = 1.0 - 0.22 * pr * pr * pr;\n    float groove = 1.0 - 0.55 * exp(-jd / 0.0035);\n    float under = 1.0 - 0.25 * smoothstep(0.75, 1.0, f2) * (1.0 - sy);\n    float onS = fuse * step(0.0, ds);\n    vec3 bs = b.rgb * mix(1.0, prof * groove * under, onS);\n    // stålets krop: et svagt, konstant skær på lamellens hvælving (følger kun porten, aldrig musikken)\n    float cr = (f2 - 0.42) / 0.16;\n    float crest = exp(-cr * cr);\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));\n    bs += seam * 0.035 * crest * onS;\n    // bundskinnen: mørkt stål med skråstriber; bliver liggende langs billedets bund og smelter ind i den nye verden\n    float st = fract((x + d) / 0.055);\n    float stripe = smoothstep(0.02, 0.06, st) * smoothstep(0.52, 0.48, st);\n    vec3 rail = b.rgb * 0.28 + seam * 0.22 * stripe;\n    bs = mix(bs, rail, inRail * fuse);\n\n    // den gamle verden: kontaktskygge under skinnen, lidt mørkere bag slidserne\n    float below = max(-d, 0.0);\n    vec3 as = a.rgb * (1.0 - 0.4 * exp(-below / 0.03) * (1.0 - inC) * smoothstep(0.0, 0.1, xt));\n    as *= 1.0 - 0.3 * slot;\n\n    float w = inC * (1.0 - slot);\n    vec4 c = vec4(mix(as, bs, w), mix(a.a, b.a, w));\n\n    // linjer: forkant (tætningslisten), skinnens overkant og en svag læbe under hvert led\n    float lw = 1.8 * px;\n    float e0 = lw * lw / (d * d + lw * lw);\n    float e1 = lw * lw / ((d - R) * (d - R) + lw * lw);\n    float lip = (1.0 - f2) * Pc - 0.004;\n    float e2 = lw * lw / (lip * lip + lw * lw) * step(0.0, ds) * inC;\n    float vis = smoothstep(0.0, 0.1, xt) * fuse;\n    c.rgb += seam * (0.3 * e0 + 0.15 * e1 + 0.14 * e2) * vis;\n    fragColor = c;\n}\n","slam":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"slam\" (hard techno): en hydraulisk presse lukker. Stempelstænger skyder to tunge stålplader med store\n// tænder ind fra toppen og bunden; pladerne bærer hver sin halvdel af den nye verden, og den gamle verden klemmes flad\n// i spalten mellem dem (lige trykket lodret, presset ud til siderne, revnet i vandrette lag), mens tænderne bider sig\n// ind i den. Pressen lukker i hak, låst til beatet: motoren blander med uMix = smoothstep(x), hvor x er tiden lineært\n// over 1 takt (drop) eller 8 takter, så x = 0, 1/4, 2/4, 3/4 altid ligger på et beat. Ved hvert af dem skyder\n// stængerne pladerne et hak ind: 60 % af vejen på ~6 frames, resten jævnt (1 takt: ét hak pr. kick; 8 takter: et\n// tungt hak hver anden takt), og imellem presser hvert beat (uBeat) et lille stød ind, der giver efter igen. Fra 3. hak\n// (x = 3/4, uMix = 0,84375) accelererer kæberne ind i hinanden og smækker i med tænderne låst, og slaget trykker den\n// nye verden kort sammen mod sømmen (~2 % af højden); resten af sidste beat smelter plader, nitter og stænger ind i\n// den nye verden, som står alene på næste downbeat. Pladerne er mørkt\n// stål med affasning, to ribber og en række nitter; alle linjer har konstant, dæmpet sømfarve. Ingen lysstyrke følger\n// musikken.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nfloat hash11(float n) { return fract(sin(n * 127.1 + 11.7) * 43758.5453); }\n\n// stød pr. beat: presser ind på ~2 frames, giver efter over resten af beatet\nfloat jolt(float ph) { return (1.0 - exp(-ph * 20.0)) * exp(-ph * 5.0); }\n// den omvendte smoothstep: overgangens tid lineært (x = k/4 ligger på et beat ved både 4 og 32 beats)\nfloat unsmooth(float m) { return 0.5 - sin(asin(1.0 - 2.0 * m) / 3.0); }\n// et hak: fuld fart fra starten, bremser op inden for w af hakkets tid\nfloat notch(float f, float w) { float t = 1.0 - clamp(f / w, 0.0, 1.0); return 1.0 - t * t; }\n// en tynd linje i afstanden dd (lorentz-profil med bredden lw)\nfloat ln(float dd, float lw) { return lw * lw / (dd * dd + lw * lw); }\n\nconst float PT = 0.18;                       // tandafstand (skærmhøjde-enheder)\nconst float T = 0.09;                        // tandhøjde\nconst float HE = 0.09;                       // pladens tykkelse bag tandroden\nconst float K = 0.6;                         // andel af hvert hak, der falder på slaget (resten glider jævnt)\nconst float W = 0.25;                        // hakkets varighed (andel af hakkets tid)\nconst float WL = 0.22;                       // slagets varighed: kæberne accelererer ind i hinanden og stopper brat\nconst float RX = 0.6;                        // stempelstængernes afstand (x = -0,6, 0, 0,6)\nconst float RW = 0.028;                      // stangens halve bredde\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    float asp = uRes.x / uRes.y;\n    float px = 1.0 / uRes.y;\n    float y = 1.0 - tc.y;                    // 0 = øverst\n    float x = (tc.x - 0.5) * asp;\n\n    float xt = unsmooth(m);\n    float j = min(floor(xt * 4.0), 3.0);     // hak nr. 0..3 (3 = slaget)\n    float f = xt * 4.0 - j;\n    float ur = (j + (j > 2.5 ? pow(min(f / WL, 1.0), 1.25) : mix(f, notch(f, W), K))) * 0.25;\n    float env = smoothstep(0.02, 0.12, xt) * (1.0 - smoothstep(0.62, 0.73, xt));\n    float jl = jolt(fract(uBeat)) * env;\n    float g0 = 1.0 + T + 0.006;              // start: tandspidserne lige uden for billedkanten\n    float g = max(g0 * (1.0 - pow(ur, 1.3)) - 0.06 * jl, 0.0);    // spaltens højde (lodret, tand mod tand)\n    // slaget: topper, idet tænderne låser, og er væk inden næste downbeat\n    float tq = clamp(xt * 4.0 - 3.0, 0.0, 1.0);\n    float tc2 = max(tq - WL, 0.0);           // tid siden tænderne låste\n    float th = (1.0 - exp(-tc2 * 60.0)) * exp(-tc2 * 9.0) * (1.0 - tq);\n    float fade = 1.0 - smoothstep(WL + 0.05, 0.8, tq);             // når pressen står lukket, smelter stålet væk\n\n    // tandprofil: trekant med let runde flanker; hældningen giver den vinkelrette afstand til kanten\n    float tri = abs(fract(x / PT) - 0.5) * 2.0;\n    float tooth = mix(tri, smoothstep(0.0, 1.0, tri), 0.35) - 0.5;\n    float slope = T * mix(1.0, 6.0 * tri * (1.0 - tri), 0.35) * 2.0 / PT;\n    float nrm = inversesqrt(1.0 + slope * slope);\n    float yc = 0.5 + T * tooth;              // spaltens midte følger tænderne\n    float dt = (yc - 0.5 * g) - y;           // > 0: i overkæben\n    float db = y - (yc + 0.5 * g);           // > 0: i underkæben\n    float aa = 1.6 * px;\n    float wT = smoothstep(-aa, aa, dt * nrm);\n    float wB = smoothstep(-aa, aa, db * nrm);\n    float wJ = min(wT + wB, 1.0);            // spalten er aldrig negativ: de to kæber overlapper ikke\n    float kT = wT / max(wT + wB, 1e-4);\n\n    // slaget trykker den nye verden sammen mod sømmen (størst ved midten, 0 ved billedkanten: ingen kantpixels)\n    float h = y - 0.5;\n    float yB = 0.5 + h * (1.0 + 0.18 * th * (1.0 - 4.0 * h * h));\n    vec4 bT = texture(uB, vec2(tc.x, 1.0 - clamp(yB + 0.5 * g, 0.0, 1.0)));\n    vec4 bB = texture(uB, vec2(tc.x, 1.0 - clamp(yB - 0.5 * g, 0.0, 1.0)));\n\n    // den gamle verden klemmes lige: rodlinjerne står G fra hinanden, og A trykkes ind imellem, højst ~4,5 gange;\n    // derefter beskæres den (tænderne bider resten af), så tynde neonlinjer ikke flimrer\n    float G = min(g + T, 1.0);\n    float sq = 1.0 - G;                      // 0 = urørt, 1 = flad\n    float Gc = max(G, 0.22);\n    float yA = 0.5 + (y - 0.5) / Gc;\n    float xA = 0.5 + (tc.x - 0.5) * (1.0 - 0.2 * sq);\n    // under trykket revner den gamle verden i vandrette lag, der skrider sidelæns (mere jo fladere, og et ryk på slaget)\n    float yAc = clamp(yA, 0.0, 0.999);\n    float layer = floor(yAc * 9.0);\n    xA += (hash11(layer) - 0.5) * (0.05 * sq * sq + 0.025 * jl * sq);\n    vec4 a = texture(uA, vec2(xA, 1.0 - clamp(yA, 0.0, 1.0)));\n    float fl = fract(yAc * 9.0);\n    float crack = min(fl, 1.0 - fl) * Gc / 9.0;                   // afstand til nærmeste revne (skærmhøjde)\n    a.rgb *= 1.0 - 0.6 * smoothstep(0.1, 0.5, sq) * exp(-crack / (3.0 * px));\n    // trykskygge på den gamle verden langs kæberne\n    float dj = max(-max(dt, db), 0.0) * nrm;\n    a.rgb *= 1.0 - 0.4 * exp(-dj / 0.02) * smoothstep(0.0, 0.12, xt);\n\n    // pladerne: fra tandkanten ind til en lige bagkant HE bag tandroden; mørkt stål\n    float up = step(y, 0.5);                 // 1 = overkæben\n    float root0 = 0.5 * (g + T);\n    float rT = 0.5 - root0 - HE;             // overpladens bagkant (y)\n    float rB = 0.5 + root0 + HE;             // underpladens bagkant\n    float inStT = wT * smoothstep(-aa, aa, y - rT);\n    float inStB = wB * smoothstep(-aa, aa, rB - y);\n    float steel = (inStT + inStB) * fade;\n    // stempelstængerne: fra billedkanten ind til pladens bagkant; de bliver længere, mens pressen lukker\n    float ue = mix(y - rB, rT - y, up);      // > 0: mellem billedkant og plade\n    float edgeDist = mix(1.0 - y, y, up);    // afstand fra billedkanten\n    float dxr = x - clamp(floor(x / RX + 0.5), -1.0, 1.0) * RX;\n    float adx = abs(dxr);\n    float inU = smoothstep(-aa, aa, ue);\n    float onRod = inU * smoothstep(RW + aa, RW - aa, adx) * fade;\n    // en fast pakdåse ved billedkanten, som stangen glider ud af\n    float gM = inU * smoothstep(0.06 + aa, 0.06 - aa, edgeDist);\n    float gland = gM * smoothstep(1.6 * RW + aa, 1.6 * RW - aa, adx) * fade;\n    vec3 jawT = bT.rgb, jawB = bB.rgb;\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));\n    // stangen er en massiv cylinder: mørk, med et blødt, konstant skær på den ene side\n    float cyl = dxr / RW;\n    float chrome = exp(-(cyl + 0.4) * (cyl + 0.4) * 9.0) * onRod;\n    vec3 jaw = mix(jawB, jawT, kT) * (1.0 - 0.84 * steel) * (1.0 - 0.8 * max(onRod, gland))\n             + seam * (0.018 * steel + 0.05 * chrome + 0.02 * gland);   // mørkt stål: den nye verden skinner kun svagt igennem\n    float depthB = mix(bB.a, bT.a, kT);\n\n    vec4 c = vec4(mix(a.rgb, jaw, wJ), mix(a.a, depthB, wJ));\n\n    // linjer (konstant, dæmpet sømfarve): tændernes kontur og en indre affasning, pladens bagkant med affasning,\n    // to ribber, en række nitter (én pr. tand) og stængernes kanter med et smalt skær\n    float lw = 1.8 * px;\n    float et = dt * nrm, eb = db * nrm;\n    float e = min(ln(et, lw) + ln(eb, lw), 1.0);\n    float eIn = (ln(et - 0.011, lw) * wT + ln(eb - 0.011, lw) * wB);\n    float uu = mix(rB - y, y - rT, up);      // afstand fra pladens bagkant ind mod tænderne\n    float inPl = smoothstep(-aa, aa, uu) * wJ;\n    float eR = ln(uu, lw);\n    float ribs = (ln(uu - 0.012, lw) + ln(uu - 0.3 * HE, lw) + ln(uu - 0.72 * HE, lw)) * inPl;\n    vec2 rv = vec2((fract(x / PT + 0.5) - 0.5) * PT, uu - 0.51 * HE);\n    float rr = abs(length(rv) - 0.0095);\n    float rivet = ln(rr, lw) * inPl;\n    float rod = ln(adx - RW, lw) * inU\n              + (ln(adx - 1.6 * RW, lw) + ln(edgeDist - 0.06, lw) * step(adx, 1.6 * RW)) * gM;\n    // stålets krop: et svagt, konstant skær nær tandroden (følger kun pladen, aldrig musikken)\n    float root = mix(y - (0.5 + root0), (0.5 - root0) - y, up);\n    float sr = (root - 0.3 * HE) / (0.35 * HE);\n    float sheen = exp(-sr * sr);\n    float vis = smoothstep(0.0, 0.1, xt) * fade;\n    c.rgb += seam * (0.28 * e + 0.08 * eIn * steel + 0.16 * eR * wJ + 0.1 * ribs * steel + 0.2 * rivet * steel\n                     + 0.05 * sheen * steel + 0.2 * rod * step(adx, 2.5 * RW)) * vis;\n    fragColor = c;\n}\n","crossfader":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"crossfader\" (4D-Klip'N'Snask): mixerens crossfader gjort synlig. En blød lodret søm i sømfarven\n// (fast lys) glider fra venstre mod højre med uMix (motoren blander allerede med en blød kurve, så sømmen\n// accelererer og bremser som en hånd på faderen). Bag sømmen (til venstre) står den nye verden B, foran den den gamle A.\n// Sømmen ligger i en smal mørk kanal (slidsen i frontpladen), så den kan læses mod travle verdener.\n// Nederst rider sømmen på en fader-knap: en høj, mørk kappe (røget akryl, blød skygge, dobbelt omrids, sømmen som\n// midterstreg og to grebsriller på tværs i hver ende), der glider i sin skinne og passerer midtermærket (skinnen lyser\n// kun op omkring knappen og følger den). Sømmen og kappen får fokus-dybden i alfakanalen, så dybdeskarpheden ikke\n// slører dem over fjern himmel; de ligger dermed mellem den rejsende (foran) og det store element (bagved).\n// Omkring sømmen er billedet dobbelt: A og B ses begge, som en crossfade i midterstilling, og de to billeder er en\n// anelse forskudt hver sin vej. Langs sømmen ligger tre \"fader-slidser\" på hver side: lodrette strimler, der er\n// forskudt op/ned mod hinanden (riller, hvor linjerne knækker), og en svag rille-bølge fra en roterende vinylplade\n// (spiralrillen, én omgang pr. 4 beats). Alt det forskyder A og B; intet ændrer lysstyrken.\n// Begge verdener trækkes en anelse med sømmen (parallakse). På hvert beat (på kickets anslag) giver sømmen et kort,\n// sprødt skub i geometrien (en lille S-bøjning med middel 0 over højden, strimlerne rykker, knappen hopper); intet lys\n// og ingen farve følger musikken.\n// Sømmen og al forvrængning er helt uden for billedet ved uMix 0 og 1 (nøjagtigt A og B).\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\n#define TAU 6.28318530718\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nvec2 mirror(vec2 t) { return 1.0 - abs(1.0 - abs(t)); }            // spejlet ved kanten (ingen kantstriber)\n// ryk pr. beat: næsten helt oppe inden for én frame, klinger af over ~4 frames (0 ved begge ender, top ~1).\n// Fasen tælles fra en halv frame før slaget (~0,024 beat ved 60 fps og 154-180 BPM), ligesom motorens kick-envelope,\n// der begynder på kickets nærmeste frame: så ligger rykket på kickets anslag og ikke en frame efter\nfloat jolt(float ph) { return (1.0 - exp(-ph * 80.0)) * exp(-ph * 6.0) * 1.31; }\n// smal neon-linje (kvadreret Lorentz-profil, ingen brede glorier)\nfloat line(float d, float w) { float l = w * w / (d * d + w * w); return l * l; }\n\nconst float HW = 0.12;        // halv bredde af den dobbelte zone (skærmhøjde-enheder)\nconst float ZR = 0.20;        // forvrængningens rækkevidde fra sømmen\nconst float MARG = 0.27;      // sømmens afstand uden for billedet ved uMix 0 og 1 (> ZR + bøjning + knap)\nconst float KNOB_Y = -0.38;   // fader-knappens højde\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    float asp = uRes.x / uRes.y;\n    vec2 p = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;   // x i [-asp/2, asp/2], y i [-0,5, 0,5]\n    float px = 1.0 / uRes.y;\n    vec2 toT = vec2(1.0 / asp, 1.0);                      // skærmhøjde-enheder -> teksturkoordinater\n\n    float X0 = 0.5 * asp + MARG;\n    float xs = mix(-X0, X0, m);\n    float jl = jolt(fract(uBeat + 0.024));\n    // sømmen lever: en langsom bølge op ad sømmen (8 beats) og et kort S-ryk på beatet; begge har middel 0 over højden\n    float bend = 0.006 * sin(TAU * (p.y + uBeat / 8.0)) + 0.005 * jl * sin(TAU * 2.0 * p.y + 0.6);\n    float d = p.x - xs - bend;                            // > 0 foran sømmen (A), < 0 bag den (B)\n    float ad = abs(d);\n\n    // vægten: B bag sømmen, A foran, midt i sømmen halvt af hver. Den dobbelte zone er bredest, når faderen står i\n    // midten (begge dæk spiller), og smallere ude mod siderne\n    float hw = HW * (0.7 + 0.45 * sin(3.14159265 * m));\n    float w = smoothstep(hw, -hw, d);\n\n    // fader-slidser: strimler mellem sømmen og tre riller på hver side, forskudt op/ned mod hinanden (0 i strimlen\n    // nærmest sømmen og uden for den yderste rille); rykker på beatet. Bløde trin (~1,5 px) mod aliasering.\n    float e = 1.5 * px;\n    float dy = 1.0 * smoothstep(0.034 - e, 0.034 + e, ad)\n             - 1.6 * smoothstep(0.072 - e, 0.072 + e, ad)\n             + 0.95 * smoothstep(0.118 - e, 0.118 + e, ad)\n             - 0.35 * smoothstep(0.170 - e, 0.170 + e, ad);\n    dy *= (0.0055 + 0.0035 * jl) * sign(d);\n    vec2 off = vec2(0.0, dy);\n\n    // vinylpladen: spiralrillen fra en plade, hvis centrum kører med sømmen (ude til højre), roterer én gang pr. 4 beats\n    vec2 C = vec2(xs + 1.25, -0.12);\n    vec2 q = p - C;\n    float r = max(length(q), 1e-4);                       // vern mod 0/0 præcis i pladens centrum\n    float th = atan(q.y, q.x);\n    float ph = r / 0.0135 + th / TAU - uBeat / 4.0;\n    float rip = exp(-d * d / (0.11 * 0.11));\n    off += (q / r) * 0.0014 * sin(TAU * ph) * rip;\n\n    // dobbelt-billedet: i zonen glider A en anelse frem og B en anelse tilbage\n    float bell = exp(-d * d / (0.08 * 0.08));\n    // parallakse: begge verdener trækkes med sømmen (A skubbes ud, B kommer ind med den); 0 ved begge ender\n    vec2 ta = tc + (off + vec2(0.010 * bell, 0.0)) * toT - vec2(0.045 * m, 0.0) * toT;\n    vec2 tb = tc + (off - vec2(0.010 * bell, 0.0)) * toT + vec2(0.045 * (1.0 - m), 0.0) * toT;\n    vec4 a = texture(uA, mirror(ta));\n    vec4 b = texture(uB, mirror(tb));\n    vec4 c = mix(a, b, w);\n\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));    // lyse sømfarver dæmpes\n    float env = smoothstep(0.0, 0.05, m) * (1.0 - smoothstep(0.95, 1.0, m));\n\n    // fader-knappen: en afrundet kappe om sømmen nederst (mørk flade, dobbelt omrids), sømmen er dens rille på tværs;\n    // den hopper en anelse på beatet (som et tap på faderen)\n    float ky = KNOB_Y + 0.004 * jl;\n    vec2 kq = vec2(d, p.y - ky);\n    vec2 kb = abs(kq) - vec2(0.022, 0.036);              // som en rigtig crossfader-kappe: højere end bred\n    float ksd = length(max(kb, 0.0)) + min(max(kb.x, kb.y), 0.0) - 0.013;\n    float kin = 1.0 - smoothstep(-e, e, ksd);\n    // sømmen ligger i en mørk kanal (som slidsen i mixerens frontplade), så den kan læses mod travle verdener;\n    // knappens flade er mørk (en massiv kappe af røget akryl), og en blød skygge om den løfter den fra verdenen\n    // (HDR: verdenernes linjer er langt over 1, så dæmpningen skal være dyb for at kunne ses)\n    float chan = exp(-d * d / (0.016 * 0.016)) * (1.0 - 0.6 * exp(-d * d / (0.0025 * 0.0025)));\n    float kshad = (1.0 - smoothstep(0.0, 0.035, ksd)) * (1.0 - kin);\n    c.rgb *= (1.0 - 0.8 * chan * env) * (1.0 - 0.9 * kin * env) * (1.0 - 0.55 * kshad * env);\n    // skinnen: to vandrette linjer gennem knappen, som klinger ud til siderne (følger knappen)\n    float tf = exp(-d * d / (0.42 * 0.42)) * (1.0 - kin);\n    float track = line(p.y - KNOB_Y - 0.008, 1.4 * px) + line(p.y - KNOB_Y + 0.008, 1.4 * px);\n    // midtermærket på skinnen (faderens midterstilling), ses kun, når knappen er i nærheden\n    track += 0.8 * line(p.x, 1.4 * px) * (1.0 - smoothstep(0.016, 0.020, abs(p.y - KNOB_Y)));\n    // slidsernes riller: meget svage linjer i sømfarven, svagere udad (de bærer forvrængningen i mørke områder)\n    float slots = 0.050 * line(ad - 0.034, 1.2 * px) + 0.035 * line(ad - 0.072, 1.2 * px)\n                + 0.022 * line(ad - 0.118, 1.2 * px) + 0.012 * line(ad - 0.170, 1.2 * px);\n\n    // sømmens lys: smal kerne + blødt blad + svag glorie; fast lys (knappen afskærer sømmen ikke)\n    float lit = 0.75 * line(d, 2.5 * px) + 0.16 * exp(-d * d / (0.006 * 0.006)) + 0.04 * exp(-d * d / (0.03 * 0.03));\n    // kappen: dobbelt omrids, sømmen som dens midterstreg og to grebsriller på tværs i hver ende\n    float kdeep = 1.0 - smoothstep(-0.012, -0.008, ksd);\n    float ridge = 0.24 * (line(abs(kq.y) - 0.022, 1.3 * px) + line(abs(kq.y) - 0.030, 1.3 * px)) * kdeep;\n    float knob = 0.60 * line(ksd, 1.8 * px) + 0.22 * line(ksd + 0.009, 1.3 * px) + ridge;\n    float glow = lit + knob + slots + 0.14 * track * tf;\n    c.rgb += seam * glow * env;\n    // sømmen og kappen er en genstand på fokus-afstanden (dybden midt i billedet, hvor autofokus måler): så står de\n    // skarpt over fjern himmel (ellers sløret af dybdeskarpheden) og ligger mellem rejsende (2,6) og det store element\n    vec2 fo = vec2(0.006, 0.010);\n    float fA = 0.2 * (texture(uA, vec2(0.5)).a + texture(uA, vec2(0.5) + fo).a + texture(uA, vec2(0.5) - fo).a\n                    + texture(uA, vec2(0.5) + vec2(fo.x, -fo.y)).a + texture(uA, vec2(0.5) - vec2(fo.x, -fo.y)).a);\n    float fB = 0.2 * (texture(uB, vec2(0.5)).a + texture(uB, vec2(0.5) + fo).a + texture(uB, vec2(0.5) - fo).a\n                    + texture(uB, vec2(0.5) + vec2(fo.x, -fo.y)).a + texture(uB, vec2(0.5) - vec2(fo.x, -fo.y)).a);\n    float d0 = -xs - 0.006 * sin(TAU * uBeat / 8.0) - 0.005 * jl * sin(0.6);\n    float fd = mix(fA, fB, smoothstep(hw, -hw, d0));\n    float own = max(smoothstep(0.1, 0.5, lit + knob), kin) * env;          // kun kernen og kappen, ikke bladet\n    c.a = mix(c.a, fd, own);\n    fragColor = c;\n}\n","frame":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Krydsning \"frame\" (MondayMonday 4/10, \"Katten i billedet\"): et svævende billede med neon-ramme kommer flyvende mod\n// kameraet gennem breaket. Først viser det kattefilmen (brugerens klip eller en lokal Wan-forlængelse), så glider\n// billedet over i et vindue ind til univers B, og på droppet flyver kameraet gennem rammen, så B fylder alt.\n// uMix: 0 = rammen er en prik langt væk, 0,55 = ca. 40 % af højden, 0,8 = filmen er blevet til B, 1 = B overalt.\n// Rammens højde vokser eksponentielt (som noget, der nærmer sig med jævn fart). Ingen lysstyrke følger musikken:\n// rammen har fast lys; den bliver kun større.\nuniform sampler2D uA, uB;\nuniform sampler2D uFilm, uFilm2;    // to nabo-billeder fra filmen (rækkefølge top -> bund) og blandingen mellem dem\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nuniform float uFilmBlend, uFilmOn, uFilmAspect, uFilmGain;\nout vec4 fragColor;\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nmat2 rot2(float a) { float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    vec4 a = texture(uA, tc);\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = a; return; }\n    vec4 b = texture(uB, tc);\n    if (m >= 1.0) { fragColor = b; return; }\n    vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    float asp = uFilmOn > 0.5 ? clamp(uFilmAspect, 0.6, 2.0) : 1.45;\n    float h = 0.03 * exp(m * log(40.0));                      // halv højde: 0,03 -> 1,2\n    float far = 1.0 - smoothstep(0.55, 0.95, m);\n    vec2 cen = far * vec2(0.10 * sin(uBeat * 6.2831853 / 32.0), 0.05 * cos(uBeat * 6.2831853 / 24.0));\n    vec2 q = rot2(0.10 * far * sin(uBeat * 6.2831853 / 64.0)) * (uv - cen);\n    // svag perspektiv-hældning: rammen drejer langsomt om sin lodrette akse, mens den er langt væk\n    float yaw = 0.18 * far * sin(uBeat * 6.2831853 / 48.0);\n    q.y *= 1.0 + yaw * q.x / max(h * asp, 1e-3) * 0.35;\n    vec2 hb = vec2(h * asp, h);\n    vec2 dq = abs(q) - hb;\n    float sd = length(max(dq, 0.0)) + min(max(dq.x, dq.y), 0.0);   // < 0 inde i billedet\n    float aa = 1.5 / uRes.y;\n    float inside = 1.0 - smoothstep(-aa, aa, sd);\n    // indholdet: film -> vindue ind til B\n    float toB = uFilmOn > 0.5 ? smoothstep(0.55, 0.8, m) : 1.0;\n    vec4 c = a;\n    if (inside > 0.0) {\n        vec4 film = b;\n        if (uFilmOn > 0.5) {\n            vec2 st = q / (2.0 * hb) + 0.5;\n            st.y = 1.0 - st.y;                                    // filmens række 0 = top\n            vec3 f1 = texture(uFilm, st).rgb, f2 = texture(uFilm2, st).rgb;\n            vec3 fc = pow(mix(f1, f2, uFilmBlend), vec3(2.2)) * uFilmGain;\n            film = vec4(fc, clamp(0.6 / h, 0.8, 30.0));           // dybden = rammens afstand (autofokus på billedet)\n        }\n        c = mix(a, mix(film, b, toB), inside);\n    }\n    // neon-rammen: dobbelt linje med fast lys i sømfarven + små runde hjørner (pladespiller-knapper)\n    vec3 seam = uSeam * min(1.0, 0.45 / max(luma(uSeam), 1e-3));\n    float w1 = 0.012 * h + 0.0012, w2 = 0.006 * h + 0.0008;\n    float d1 = abs(sd - 0.5 * w1 - 0.002 * h), d2 = abs(sd - 0.045 * h);\n    vec2 cq = abs(q) - hb;                                        // hjørnerne\n    float dc = abs(length(cq) - 0.06 * h);\n    float line = smoothstep(w1, 0.0, d1) + 0.6 * smoothstep(w2, 0.0, d2) + 0.8 * smoothstep(w2, 0.0, dc);\n    float glow = 0.25 * (w1 * w1 / (d1 * d1 + w1 * w1));\n    float edgeFade = 1.0 - smoothstep(0.85, 1.0, m);              // rammen er væk, når B fylder alt\n    c.rgb += seam * (line + glow) * edgeFade * smoothstep(0.0, 0.04, m);\n    fragColor = c;\n}\n","gate":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"gate\" (4D-Klip'N'Snask, 03:12 -> 03:17 og 60:47 -> 61:09): gateren gjort synlig. To gange i sættet\n// kommer det næste nummer ind gennem en gater (lyden hakkes på sekstendedelene, og gaten åbner mere og mere, til det\n// nye nummer har taget over). Billedet skæres i 21 lodrette, let skrå skiver (lameller i en port); i hver skive ses\n// enten den gamle verden A eller den nye B. Mønsteret springer til en ny opstilling på hver sekstendedel\n// (floor(uBeat*4) som frø, kun geometri), og andelen af skiver med B vokser med uMix.\n// Lysstyrken holdes jævn: opstillingen er et Fibonacci-gitter (rang = (i*k + skub) mod 21, k = 13/8/5/16), så B-skiverne\n// altid ligger spredt over hele billedet, og præcis uMix*21 skiver viser B (den ene skive, der er på vej, åbner fra sin\n// midte som en spalte, der vokser jævnt med uMix). Der skiftes aldrig hele billedet mellem A og B.\n// Skivekanterne har en tynd søm i sømfarven med fast lys i alle kanter (antallet af sømme er altid det samme), og\n// kanterne rykker en anelse sidelæns ved hvert spring; indholdet i hver skive får et lille sideryk (og et endnu mindre\n// hop op/ned), der klinger af inden næste sekstendedel, kraftigst på slaget (kickets anslag), og på slaget får\n// hældningen et kort skub. Et afspilningshoved som på en trinsekvenser løber over porten én gang pr. takt (16 trin): den\n// skive, trinnet står i, hopper op og falder tilbage (kun indholdets placering). Begge verdener glider en\n// anelse frem (zoom ind), som om kameraet går gennem porten. Intet lys og ingen farve følger musikken.\n// Nøjagtigt A ved uMix 0 og nøjagtigt B ved uMix 1.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\n#define TAU 6.28318530718\nconst int   N = 21;                  // antal skiver (Fibonacci-tal: k = 13 og 8 giver det jævneste gitter)\nconst float FN = 21.0;\nconst float SLANT = 0.12;            // skivernes hældning (x pr. y; ~7 grader)\nconst float JIT = 0.20;              // kanternes sideryk pr. opstilling (andel af en skivebredde)\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nvec2 mirror(vec2 t) { return 1.0 - abs(1.0 - abs(t)); }            // spejlet ved kanten (ingen kantstriber)\n// smal neon-linje (kvadreret Lorentz-profil, ingen brede glorier)\nfloat line(float d, float w) { float l = w * w / (d * d + w * w); return l * l; }\n// heltals-hash (stabil også ved store sekstendedels-numre sidst i sættet)\nuint hsh(uint x) { x ^= x >> 16; x *= 0x7feb352du; x ^= x >> 15; x *= 0x846ca68bu; x ^= x >> 16; return x; }\nfloat h01(uint a, uint b) { return float(hsh(hsh(a) ^ (b * 0x9e3779b9u)) >> 8) / 16777216.0; }\n\nuint gSeed;\n// kant nr. k (i skive-enheder); de to yderkanter ligger fast (uden for billedet)\nfloat edgeAt(int k) {\n    if (k <= 0 || k >= N) return float(k);\n    return float(k) + JIT * (2.0 * h01(gSeed, uint(k) + 101u) - 1.0);\n}\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n\n    float asp = uRes.x / uRes.y;\n    vec2 p = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;   // x i [-asp/2, asp/2], y i [-0,5, 0,5]\n    float px = 1.0 / uRes.y;\n    vec2 toT = vec2(1.0 / asp, 1.0);\n\n    // sekstendedelen: fasen tælles fra en halv frame før slaget (~0,1 sekstendedel ved 60 fps og 154-180 BPM), så\n    // springet ligger på anslagets frame\n    float s16 = uBeat * 4.0 + 0.096;\n    float jf = floor(s16);\n    float ph = s16 - jf;\n    int ji = int(jf) + 1048576;                          // positivt (deleligt med 4: samme fase i takten)\n    gSeed = uint(ji);\n    bool onBeat = (ji % 4) == 0;\n\n    // sømme og ryk toner ind og ud i overgangens yderste procenter (0 ved begge ender)\n    float env = smoothstep(0.0, 0.06, m) * (1.0 - smoothstep(0.94, 1.0, m));\n\n    // springets ryk: klinger af inden næste sekstendedel; kraftigst på slaget (kickets anslag)\n    float jl = exp(-ph * 4.5) * (onBeat ? 1.0 : 0.55) * env;\n    float jk = onBeat ? exp(-ph * 4.5) * env : 0.0;\n\n    // skivegitteret: let skråt, hældningen svajer langsomt (16 beats) og får et kort skub på slaget\n    float sl = SLANT + 0.035 * sin(TAU * uBeat / 16.0) + 0.03 * jk;\n    float span = asp + 0.2;                              // dækker billedet ved alle hældninger\n    float w = span / FN;                                 // skivebredde (vandret, skærmhøjde-enheder)\n    float cs = inversesqrt(1.0 + sl * sl);               // vandret -> vinkelret på kanten\n    float u = (p.x + p.y * sl + 0.5 * span) / w;         // 0..N\n    int i = int(floor(u));\n    float lo = edgeAt(i), hi = edgeAt(i + 1);\n    if (u < lo) { i -= 1; hi = lo; lo = edgeAt(i); }\n    else if (u > hi) { i += 1; lo = hi; hi = edgeAt(i + 1); }\n\n    float sw = (hi - lo) * w * cs;                       // skivens bredde vinkelret på kanterne\n    float x0 = (u - lo) * w * cs, x1 = (hi - u) * w * cs;\n    float de = min(x0, x1);                              // afstand til nærmeste kant\n    float dc = abs(x0 - 0.5 * sw);                       // afstand fra skivens midterlinje\n\n    // opstillingen: rang = (i*k + skub) mod N; B, hvor rangen ligger under uMix*N\n    uint hm = hsh(gSeed * 3u + 7u);\n    int sel = int(hm & 3u);\n    int k = sel == 0 ? 13 : (sel == 1 ? 8 : (sel == 2 ? 5 : 16));\n    int sh = int((hm >> 8) % uint(N));\n    float mN = m * FN;\n    float f = clamp(mN - float((i * k + sh) % N), 0.0, 1.0);\n    // den skive, der er på vej, åbner som en spalte fra midten (blød kant på ~1 px)\n    float wB = f >= 1.0 ? 1.0 : clamp((f * 0.5 * sw - dc) / px + 0.5, 0.0, 1.0);\n    // kantudglatning mod naboskiven\n    int nb = x0 < x1 ? i - 1 : i + 1;\n    float vn = (nb < 0 || nb >= N) ? wB : step(1.0, mN - float((nb * k + sh) % N));\n    wB = mix(vn, wB, clamp(0.5 + de / px, 0.0, 1.0));\n\n    // springet: hver skive får et sideryk (og et lille hop op/ned)\n    uint si = uint(clamp(i, 0, N - 1));\n    float rx = 2.0 * h01(gSeed, si + 301u) - 1.0;\n    float ry = 2.0 * h01(gSeed, si + 607u) - 1.0;\n    vec2 off = vec2(0.0065 * rx, 0.0035 * ry) * jl;\n    // trinsekvenserens afspilningshoved: takten har 16 trin fordelt over billedets bredde; den skive, trinnet står i,\n    // hopper op (indholdet løftes og falder tilbage inden næste trin), så et lille hop løber over porten hver takt\n    float step16 = float(ji % 16);\n    float xh = (step16 + 0.5) / 16.0 * asp - 0.5 * asp;            // trinnets plads (ved y = 0)\n    float uh = (xh + 0.5 * span) / w;\n    int ih = int(floor(uh));\n    float lh = edgeAt(ih), hh = edgeAt(ih + 1);\n    if (uh < lh) ih -= 1; else if (uh > hh) ih += 1;\n    off.y -= (i == ih ? 0.011 * exp(-ph * 3.0) * env : 0.0);\n\n    // gennem porten: begge verdener glider en anelse frem (zoom ind); 0 for B ved uMix 1\n    float kA = 1.0 - 0.03 * m;\n    float kB = 1.0 + 0.03 * (1.0 - m);\n    vec2 ta = vec2(0.5) + (p * kA + off) * toT;\n    vec2 tb = vec2(0.5) + (p * kB + off) * toT;\n    vec4 a = texture(uA, mirror(ta));\n    vec4 b = texture(uB, mirror(tb));\n    vec4 c = mix(a, b, wB);\n\n    // sømmene: en mørk kanal (mellemrummet mellem lamellerne) og en tynd linje i sømfarven; fast lys i alle kanter\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));    // lyse sømfarver dæmpes\n    // (mellemrummet bliver smallere, efterhånden som gaten åbner: følger kun uMix)\n    float cw = mix(0.005, 0.003, m);\n    float chan = exp(-de * de / (cw * cw));\n    c.rgb *= 1.0 - 0.7 * chan * env;\n    float lit = 0.36 * line(de, 1.4 * px) + 0.05 * exp(-de * de / (0.0035 * 0.0035));\n    // spaltens læber (den skive, der åbner): to linjer, der fødes som én revne midt i skiven og glider ud til kanterne\n    // med uMix; fast styrke, så den samlede linjelysmængde er konstant (ved f = 1 ligger læberne oven i kantsømmene, og\n    // i samme øjeblik fødes revnen i den næste skive)\n    float hw = f * 0.5 * sw;\n    float lip = (f > 0.0 && f < 1.0) ? 0.36 * line(dc - hw, 1.4 * px) : 0.0;\n    c.rgb += seam * (lit + lip) * env;\n\n    // sømmene er en genstand på fokus-afstanden (dybden midt i billedet), så dybdeskarpheden ikke slører dem\n    vec2 fo = vec2(0.006, 0.010);\n    float fA = 0.2 * (texture(uA, vec2(0.5)).a + texture(uA, vec2(0.5) + fo).a + texture(uA, vec2(0.5) - fo).a\n                    + texture(uA, vec2(0.5) + vec2(fo.x, -fo.y)).a + texture(uA, vec2(0.5) - vec2(fo.x, -fo.y)).a);\n    float fB = 0.2 * (texture(uB, vec2(0.5)).a + texture(uB, vec2(0.5) + fo).a + texture(uB, vec2(0.5) - fo).a\n                    + texture(uB, vec2(0.5) + vec2(fo.x, -fo.y)).a + texture(uB, vec2(0.5) - vec2(fo.x, -fo.y)).a);\n    float own = smoothstep(0.1, 0.5, lit + lip) * env;\n    c.a = mix(c.a, mix(fA, fB, m), own);\n    fragColor = c;\n}\n","collapse":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Kapitelskift \"collapse\" (4D-Klip'N'Snask 118:35 -> 118:56; brugerens lyttenote: \"et univers, der falder ind i sig\n// selv og bliver til ingenting; det nye mørke univers starter 118:56\"). Lang overgang (~21 s).\n// Den gamle verden løber ud i et afløb: et arealbevarende sug (r_kilde^2 = r^2 + Q) med en hvirvel, der snor sig\n// logaritmisk ind mod centrum, så billedet trækkes ind i en langsom, accelererende spiral. Verdenen fortsætter spejlet\n// et stykke uden for rammen og toner blødt ud; kanterne krummer ind som spiralarme. Lys, der presses sammen mod\n// centrum, slukker (som rødforskydning), og i hullet ses verdenen igen, mindre og drejet, og i dens hul igen (lagene\n// falder ind i hinanden). Lyset drænes jævnt over ~13 s (lineær tid: motoren easer uMix med smoothstep, og den inverse\n// giver tiden x). Tilbage bliver en svag glød i centrum med to svage spiralarme af støv og nogle støvkorn, der kredser\n// ind mod den (uMix ~0,75-0,85). Derefter vælter den nye verden ud af gløden: samme afløb baglæns (Q falder til 0),\n// hvirvlen drejer videre samme vej og retter sig ud, og lyset stiger eksponentielt og breder sig fra gløden og udad\n// (en blød front, der når hjørnerne lige før slutningen). Nøjagtig A ved 0, B ved 1.\n// Ingen lysstyrke følger musikken: lys og farve følger kun overgangens tid; uBeat flytter kun støvkorn og spiralarme\n// (hele omløb pr. 64 slag) og ånder gløden svagt over 16 slag.\nuniform sampler2D uA, uB;\nuniform vec2 uRes;\nuniform float uMix;\nuniform vec3 uSeam;\nuniform float uBeat;\nout vec4 fragColor;\n\n#define TAU 6.28318530718\n#define DBG 0                // kun forhåndsvisning: 1 = slutningen (uMix 0,7-1) over arket, 2 = begyndelsen i detalje\n\nconst float XE  = 0.74;      // sammenstyrtningen er fuldbyrdet (lineær tid; uMix ~0,82)\nconst float QM  = 2.60;      // sugets slutstyrke (det spejlede rand-område rækker til r^2 ~ 2,5)\nconst float KAP = 0.38;      // logaritmisk snoning ind mod centrum\nconst float OMG = 2.60;      // hvirvlens drejning i centrum (rad)\nconst float C2  = 0.12;      // hvirvlens kerne (r^2)\nconst float XF  = 0.55;      // verdenen fortsætter spejlet uden for rammen og toner ud over denne afstand\nconst float DT  = 0.010;     // lysspor bagud i tid (lineær tid; ~0,2 s ved 21 s)\nconst float LS  = 2.4;       // de indre lag: mindre med denne faktor\nconst float LR  = 0.85;      // og drejet\nconst float LB  = 0.5;       // og svagere\nconst float LAG = 0.035;     // og lidt bagud i tid (mindre sammenstyrtede)\nconst float XB  = 0.60;      // den nye verden begynder at vælte ud (ses først fra uMix ~0,8)\nconst float QB  = 2.00;\nconst float KB  = 2.2;       // B's lys stiger eksponentielt\nconst float RB  = 0.25;      // B's mørke kerne (andel af suget)\nconst float FB  = 1.5;       // B's lysfront: radius FB*u, blød over WB\nconst float WB  = 0.45;\n\nfloat ASP, PX;\n\nfloat luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }\nfloat unsmooth(float m) { return 0.5 - sin(asin(1.0 - 2.0 * m) / 3.0); }\n// skærm (højde-enheder) -> tekstur, spejlet ved rammen (verdenen fortsætter uden for billedet)\nvec2 toTc(vec2 p) { vec2 t = vec2(p.x / ASP, p.y) + 0.5; return 1.0 - abs(1.0 - abs(t)); }\n// 1 i rammen, toner blødt ud i det spejlede område (kontinuert ved kanten: ingen kant ved uMix 0+); spejlbilledet\n// dæmpes, så kalejdoskop-sømmen ved rammen ikke trækker blikket\nfloat ext(vec2 p) {\n    vec2 q = abs(p) - vec2(0.5 * ASP, 0.5);\n    float d = max(q.x, q.y);\n    return (1.0 - smoothstep(0.0, XF, d)) * exp(-2.5 * max(d, 0.0));\n}\nvec2 sub(int j) { return fract(vec2(0.7548777, 0.5698403) * float(j + 1)) - 0.5; }\n\n// A set fra skærmpunktet p ved tiden x; sc/rot = det indre lags skala og drejning. n prøver: lysspor bagud i tid +\n// spredning inden for pixlen (mod aliasering, hvor billedet presses sammen)\nvec3 layerA(vec2 p, float x, float sc, float rot, int n, float spr0, out float cov, out float dep) {\n    vec3 acc = vec3(0.0);\n    cov = 0.0;\n    float da = 0.0, wd = 1e-4;\n    float s0 = clamp(x / XE, 0.0, 1.0);\n    float comp = sqrt(1.0 + QM * s0 * s0 * s0 / max(dot(p, p) * sc * sc, 1e-6));\n    float spr = spr0 * sc * clamp(comp, 1.0, 5.0);\n    for (int j = 0; j < 6; j++) {\n        if (j >= n) break;\n        float fj = (float(j) + 0.5) / float(n);\n        vec2 q = (p + sub(j) * spr * PX) * sc;\n        float s = clamp((x - DT * fj * spr0) / XE, 0.0, 1.0);\n        float Q = QM * s * s * s;\n        float r2 = dot(q, q);\n        float R2 = r2 + Q;\n        float ths = atan(q.y, q.x) + rot - KAP * s * log(R2 / max(r2, 1e-9)) - OMG * s * s * C2 / (r2 + C2);\n        vec2 src = sqrt(R2) * vec2(cos(ths), sin(ths));\n        float w = ext(src) * (r2 / max(R2, 1e-9));\n        vec4 t = texture(uA, toTc(src));\n        acc += t.rgb * w;\n        cov += w;\n        da += t.a * w;\n        wd += w;\n    }\n    cov /= float(n);\n    dep = da / wd;\n    return acc / float(n);\n}\n\n// B vælter ud af centrum: samme afløb baglæns; hvirvlen drejer videre samme vej og retter sig ud\nvec3 layerB(vec2 p, float u, float spr0, out float dep) {\n    vec3 acc = vec3(0.0);\n    float da = 0.0, wd = 1e-4;\n    float v0 = 1.0 - u;\n    float comp = sqrt(1.0 + QB * v0 * v0 * v0 / max(dot(p, p), 1e-6));\n    float spr = spr0 * clamp(comp, 1.0, 5.0);\n    for (int j = 0; j < 4; j++) {\n        float fj = (float(j) + 0.5) / 4.0;\n        vec2 q = p + sub(j) * spr * PX;\n        float v = min(1.0, v0 + 0.02 * fj * spr0);\n        float Q = QB * v * v * v;\n        float r2 = dot(q, q);\n        float R2 = r2 + Q;\n        float ths = atan(q.y, q.x) + 0.30 * v * log(R2 / max(r2, 1e-9)) + 2.2 * v * v * C2 / (r2 + C2);\n        vec2 src = sqrt(R2) * vec2(cos(ths), sin(ths));\n        // svagere \"rødforskydning\" end A's (kun en lille mørk kerne under gløden), så B's lys kan vælde ud fra centrum\n        float w = ext(src) * (r2 / max(r2 + RB * Q, 1e-9));\n        vec4 t = texture(uB, toTc(src));\n        acc += t.rgb * w;\n        da += t.a * w;\n        wd += w;\n    }\n    dep = da / wd;\n    // lyset breder sig fra gløden og udad: en blød front, der når forbi hjørnerne (r ~1,02) ved u ~0,98\n    float F = FB * u;\n    return acc * 0.25 * (1.0 - smoothstep(F - WB, F, length(p)));\n}\n\nvec3 hash3(float n) { return fract(sin(vec3(n * 127.1 + 3.1, n * 311.7 + 17.3, n * 74.7 + 41.9)) * 43758.5453); }\n\n// resten af den gamle verden: glød i centrum, to svage spiralarme af støv og støvkorn, der kredser ind mod gløden.\n// Lys kun efter overgangens tid; uBeat drejer arme og korn (hele omløb pr. 64 slag, så mod() ikke springer)\nvec3 remnant(vec2 p, float x, float u, vec3 seam) {\n    vec3 col = vec3(0.0);\n    float r = length(p);\n    float bt = mod(uBeat, 64.0);\n    float N = smoothstep(0.30, 0.66, x) * (1.0 - smoothstep(0.25, 1.0, u));\n    if (N > 0.0) {\n        float th = atan(p.y, p.x);\n        float arm = 0.5 + 0.5 * cos(2.0 * (th + 1.6 * log(max(r, 1e-3)) - TAU * bt / 64.0));\n        arm = mix(0.5, arm * arm, smoothstep(0.01, 0.06, r));\n        float br = 1.0 + 0.05 * sin(TAU * uBeat / 16.0);\n        float sg = 0.0045 * (1.0 + 1.0 * u);\n        vec3 hot = mix(seam, vec3(luma(seam)), 0.4);\n        col += N * br * (hot * 3.2 * exp(-r * r / (2.0 * sg * sg))\n                         + seam * (0.045 * exp(-r / 0.04) + 0.075 * exp(-r / 0.22) * (0.3 + 0.9 * arm)));\n    }\n    float D = smoothstep(0.40, 0.60, x) * (1.0 - smoothstep(0.35, 0.85, u));\n    if (D > 0.0) {\n        vec3 sp = vec3(0.0);\n        for (int i = 0; i < 11; i++) {\n            vec3 h = hash3(float(i));\n            float rho0 = 0.10 + 0.40 * h.x;\n            float k = rho0 < 0.22 ? 3.0 : (rho0 < 0.36 ? 2.0 : 1.0);   // indre korn kredser hurtigere\n            float ang = TAU * h.y + TAU * k / 64.0 * bt;\n            float rho = rho0 * exp(-1.3 * max(x - 0.42, 0.0)) * (1.0 + 2.2 * u * u);\n            vec2 d = p - rho * vec2(cos(ang), sin(ang) * 0.82);\n            float sg = 0.0024 + 0.0012 * h.z;\n            sp += seam * (0.4 + 0.8 * h.z) * exp(-dot(d, d) / (2.0 * sg * sg));\n        }\n        col += D * 1.6 * sp;\n    }\n    return col;\n}\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    float m = clamp(uMix, 0.0, 1.0);\n#if DBG == 1\n    m = m > 0.0 ? 0.70 + 0.30 * m : 0.0;\n#elif DBG == 2\n    m = m >= 1.0 ? 0.15 : 0.58 * m;\n#endif\n    if (m <= 0.0) { fragColor = texture(uA, tc); return; }\n    if (m >= 1.0) { fragColor = texture(uB, tc); return; }\n    ASP = uRes.x / uRes.y;\n    PX = 1.0 / uRes.y;\n    vec2 p = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    float x = unsmooth(m);\n    vec3 seam = uSeam * min(1.0, 0.3 / max(luma(uSeam), 1e-3));\n\n    // den gamle verden: lag på lag ind i hullet; lyset drænes jævnt\n    float sA = clamp(x / XE, 0.0, 1.0);\n    float gA = exp(-0.3 * sA - 1.2 * sA * sA * sA * sA) * (1.0 - smoothstep(0.85, 1.0, sA));\n    vec3 colA = vec3(0.0);\n    float T = 1.0, dA = 6e-4, wA = 1e-4;\n    float sprA = smoothstep(0.0, 0.04, x);\n    if (gA > 1e-4) {\n        for (int k = 0; k < 3; k++) {\n            float cov, dep;\n            float sc = pow(LS, float(k));\n            vec3 c = layerA(p, x - LAG * float(k), sc, LR * float(k), k == 0 ? 5 : 3, sprA, cov, dep);\n            colA += T * pow(LB, float(k)) * c;\n            dA += T * cov * dep;\n            wA += T * cov;\n            T *= 1.0 - smoothstep(0.0, 0.5, cov);      // de indre lag ses kun i hullet\n            if (T < 0.01) break;\n        }\n        colA *= gA;\n    }\n\n    // den nye verden\n    float u = clamp((x - XB) / (1.0 - XB), 0.0, 1.0);\n    vec3 colB = vec3(0.0);\n    float dB = 6.0;\n    if (u > 0.0) {\n        float gB = (exp(KB * u) - 1.0) / (exp(KB) - 1.0);\n        colB = layerB(p, u, 1.0 - smoothstep(0.85, 1.0, u), dB) * gB;\n    }\n\n    vec3 c = colA + colB + remnant(p, x, u, seam);\n    // dybde (lysvægtet, til dybdeskarphed og element-lagets okklusion): A's, hvor A stadig ses, ellers B's\n    float depth = mix(dA / wA, dB, smoothstep(0.0, 0.5, u));\n    fragColor = vec4(c, depth);\n}\n","vokser":"#version 300 es\nprecision highp float;\nprecision highp int;\n// Bro-overgangen (bridge.py, kun med --bridges): verden B vokser ind omkring BÆREREN. B's eget pas er allerede renderet\n// med uBrMode = grow (B's geometri vokser ud i en kugle om bæreren); her breder B sig på skærmen ud fra bærerens sted\n// (uCen) med en organisk, langsomt drivende kant. Ingen lysspring: kanten er svag, og alt følger uMix (langsom).\nuniform sampler2D uA, uB;\nuniform vec2 uRes, uCen;\nuniform float uMix;\nuniform vec3 uSeam;\nout vec4 fragColor;\n\nfloat h12(vec2 p) { vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }\nfloat n2(vec2 p) {\n    vec2 i = floor(p), f = fract(p);\n    f = f * f * (3.0 - 2.0 * f);\n    return mix(mix(h12(i), h12(i + vec2(1, 0)), f.x), mix(h12(i + vec2(0, 1)), h12(i + vec2(1, 1)), f.x), f.y);\n}\n\nvoid main() {\n    vec2 tc = gl_FragCoord.xy / uRes;\n    vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;\n    vec4 a = texture(uA, tc), b = texture(uB, tc);\n    float n = 0.65 * n2(uv * 3.1 + vec2(1.7 * uMix, -1.1 * uMix)) + 0.35 * n2(uv * 7.3 - vec2(0.9 * uMix, 2.0 * uMix));\n    float d = length(uv - uCen) + 0.35 * (n - 0.5);\n    float R = uMix * 2.2 - 0.3;\n    float m = smoothstep(R + 0.05, R - 0.4, d);\n    m = max(m, smoothstep(0.8, 1.0, uMix));\n    vec4 c = mix(a, b, m);\n    float e = exp(-pow((d - R + 0.12) / 0.07, 2.0));\n    c.rgb += uSeam * e * 0.06 * (1.0 - abs(2.0 * uMix - 1.0));\n    fragColor = c;\n}\n"}};
